insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('puerto-viejo-costa-rica', '10S', 'Puerto Viejo (Southern Caribbean)', 'Costa Rica', 'Costa Rica''s Southern Caribbean', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","culture","wildlife","ocean"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":["Puerto Viejo de Talamanca is Costa Rica''s Southern Caribbean counter-culture coast: Afro-Caribbean + Bribri, reggae-slow beach towns, distinct from the Pacific side.","The Caribbean coast INVERTS the national weather pattern - driest and calmest in Sep-Oct and Feb-Mar, exactly when the Pacific is ''green season'' - a counter-seasonal selling point.","Cahuita National Park protects both a coral reef (guided snorkel only, ~$20pp) and a coastal rainforest walk with sloths, monkeys, iguanas and coatis.","Salsa Brava is an expert-only shallow reef break over sharp coral; beginners surf the Playa Cocles beach break; Punta Uva and Manzanillo are the calm swimming beaches.","Access is international via SJO (San Jose), then a ~4-4.5 hr drive southeast via Limon - a real distance, not a short transfer."],"safety":{"emergency":"911","ambulance_alt":"128 (Red Cross)","hospital":"24-hr private clinic in Puerto Viejo + public clinic Hone Creek (~5km); nearest hospital Limon (~1hr); major trauma routes to San Jose","medical_evacuation":"AirMed/Global Rescue-type air ambulance toward San Jose/repatriation; ~US$50,000 often full straight","advisory_level":"L2","book_enabled":true,"l2_disclosure":true,"petty_crime":"opportunistic theft is main risk (phones/wallets/purses); don''t leave beach valuables unattended, avoid poorly lit streets alone at night, don''t resist a robbery","air_access_verified":"SJO (San Jose) -> ~4-4.5 hr drive via Limon to Puerto Viejo (distance flag)","riptide":"Caribbean riptide risk; Salsa Brava = expert-only reef break over sharp coral; swim at calmer beaches (Punta Uva, Manzanillo)","wildlife":"snake/wildlife on jungle & national-park trails - go guided, stay on trail, no-touch","dengue":"seasonal mosquito-borne risk, occasional outbreaks; repellent advised","malaria":"low/localized; negligible in beach-town zone; relevant only for deep-forest hikes","water":"generally potable in Costa Rica incl. most of this zone; sensitive travelers/remote lodges may prefer bottled - confirm at property","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-19","page_updated":"2026-05-19T11:42:25+01:00"}},"timing":{"counter_seasonal_peak_1":"Sep-Oct (Caribbean INVERTS national pattern: driest/calmest, best Cahuita snorkel visibility, rates ~30% lower)","counter_seasonal_peak_2":"Feb-Mar (driest most-reliable beach weather; least rain in March ~175mm)","surf_curve":"Salsa Brava swell Dec-Mar (dry-season window)","green_wet_variance":"wettest in the between-season troughs (~May-Aug bracket + secondary Nov-Dec lift); sell insured/refundable, lead with wildlife+reef-between-fronts","events":"Limon Carnival every October (Limon city; soca/calypso/reggae; Puerto Viejo lodging hub) + local Puerto Viejo/Manzanillo calypso nights (confirm 2026 dates)","booking_window_lead_time":"Sep-Oct value 3-5 weeks; Feb-Mar dry peak 6-10 weeks; Limon-Carnival Oct lodging 4-8 weeks","fill_the_beds":"wet troughs lead with Jaguar Rescue Center, Sloth Sanctuary, Bribri cacao tour, indoor culture + reef/beach between fronts","campaign_start_trigger":"Sep-Oct counter-seasonal push fires mid-late Aug 2026 (headline); Feb-Mar + Salsa Brava fires late-Dec 2025/early-Jan 2026; Limon-Carnival fires late-Aug/early-Sep 2026","fire_date":"2026-08-17"},"jewels":[{"name":"Cahuita National Park - reef snorkel + coastal wildlife walk","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","bookable_category":"guided snorkel + wildlife hike","source":"https://mytanfeet.com/costa-rica-national-park/cahuita-national-park-costa-rica/","si":"expedition","blurb":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","commission":"local-operator direct / affiliate 4-8%; park entry ($5 Puerto Vargas) + guide fee (~$20pp) pass-through"},{"name":"Punta Uva + Playa Cocles + Punta Cocles beach corridor","si_tag":"Tropical Islands / Beaches","status":"live","tier":"essential","hook":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","bookable_category":"self-guided beach","source":"https://mytanfeet.com/costa-rica-beach-information/punta-uva-puerto-viejo/","si":"Tropical Islands / Beaches","blurb":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","commission":"none direct (drives lodging + F&B + kayak/surf attach)"},{"name":"Manzanillo / Gandoca-Manzanillo Wildlife Refuge","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","bookable_category":"guided snorkel/dolphin-watch + coastal hike","source":"https://costarica.org/beaches/caribbean/manzanillo/","si":"wildlife","blurb":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","commission":"local-operator direct / affiliate; refuge entry pass-through"},{"name":"Jaguar Rescue Center","si_tag":"Wildlife & Nature","status":"future","tier":"essential","hook":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","bookable_category":"scheduled guided tour","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","commission":"affiliate / operator direct; admission largely pass-through/donation"},{"name":"Sloth Sanctuary (Cahuita)","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","bookable_category":"guided sanctuary + canoe tour","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","commission":"affiliate / operator direct; admission pass-through"},{"name":"Bribri indigenous territory + cacao/chocolate tour","si_tag":"Culture & Heritage","status":"future","tier":"comfort","hook":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","bookable_category":"community cultural tour","source":"https://williestourscostarica.com/tours-old/bribri-indigenous-village-chocolate-tour-medicinal-plants/","si":"culture","blurb":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","commission":"community-operator direct / affiliate; community fee pass-through"},{"name":"Salsa Brava reef break (watch or expert-only surf)","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","bookable_category":"expert self-guided / beginner-beach coaching","source":"https://www.kimkim.com/e/surf-lessons-at-salsa-brava-in-puerto-viejo-de-talamanca","si":"expedition","blurb":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","commission":"affiliate on beginner surf lessons/rentals; watching free (F&B attach)"},{"name":"Punta Uva clear-kayak (jungle river + emerald coast)","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","bookable_category":"guided clear-kayak","source":"https://caribesurcr.com/tour-item/clear-kayak-tour/","si":"ocean","blurb":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","commission":"affiliate / operator direct"},{"name":"Afro-Caribbean cuisine (rondon + rice-and-beans in coconut)","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","bookable_category":"self-guided + food/culture tours","source":"https://soullifetravel.net/bribri-chocolate-indigenous-culture-costa-rica/","si":"culture","blurb":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","commission":"affiliate on food tours; otherwise F&B attach"},{"name":"Limon Carnival (October) + calypso nights","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","bookable_category":"self-guided + festival-week lodging","source":"https://www.takeyourbackpack.com/backpacking-in-costa-rica/visit-limon-carnival/","si":"culture","blurb":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","commission":"lodging AOR + affiliate on festival transfers"}],"faq":[{"q":"Do you need a guide to snorkel Cahuita National Park?","a":"Yes — Cahuita''s reef snorkel is guided-only (~US$20 pp); you can''t bring your own gear and go solo, single-use plastics are banned, and no-touch coral discipline applies. Book the guided boat snorkel for best visibility Mar–Apr and Aug–Oct.","source":"mytanfeet.com, 2026-07-06","si_tag":"expedition"},{"q":"Is Puerto Viejo good for a honeymoon?","a":"Yes, as barefoot-luxury rather than palace-luxury. The ceiling is premier-to-luxury boutique — Le Cameleon (SLH) from ~US$186/night, or the 7-bungalow Tierra de Sueños wellness hideaway in Playa Chiquita — jungle-beach seclusion, adults-leaning, no marble required.","source":"lecameleonhotel.com, 2026-07-06","si_tag":"romance"},{"q":"When is Limón Carnival, and can you base in Puerto Viejo for it?","a":"Yes. Limón Carnival runs every October (started 1949) in the port city of Limón — soca, calypso, reggae and parades — with Puerto Viejo a common lodging hub a short hop south; confirm exact 2026 dates on live tracking.","source":"takeyourbackpack.com, 2026-07-06","si_tag":"culture"},{"q":"Can you see sloths and dolphins around Puerto Viejo?","a":"Easily. The town is ringed by jungle, so sloths, monkeys and colorful birds show right off the coast road, and the 23,348-acre Gandoca-Manzanillo refuge holds year-round bottlenose and tucuxi dolphins plus four sea-turtle species (Mar–Jul).","source":"costarica.org, 2026-07-06","si_tag":"wildlife"},{"q":"Can beginners surf Salsa Brava?","a":"No. Salsa Brava is an expert-only, powerful, shallow reef break over sharp coral — one of Central America''s heaviest waves — and it injures those who fall. Beginners and intermediates belong at the Playa Cocles beach break or a gentler beach; distinguish clearly at point of sale.","source":"kimkim.com, 2026-07-06","si_tag":"safety"},{"q":"How far is medical care if something goes wrong?","a":"A 24-hour private clinic in Puerto Viejo handles emergencies, with a public clinic in Hone Creek (~5 km) and the nearest large hospital in Limón (~1 hr); major trauma routes to San José. Air-evac cases can run ~US$50,000, often full straight — carry robust travel + air-evac insurance.","source":"puntauvarealty.com, 2026-07-06 · remax-oceansurf-cr.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Puerto Viejo de Talamanca, Costa Rica Travel Guide 2026 - Southern Caribbean, Sloths, Salsa Brava & Cahuita | TravelWell.World","meta_description":"Plan Costa Rica''s Southern Caribbean: Puerto Viejo de Talamanca, Cahuita reef & wildlife, Punta Uva & Manzanillo beaches, Salsa Brava surf, Bribri chocolate, boutique jungle-beach lodges, straight L2 safety, and the counter-seasonal Sep-Oct sweet spot.","slug":"puerto-viejo-costa-rica","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"es-CR","primary_keywords":["Puerto Viejo Costa Rica travel guide","Southern Caribbean Costa Rica","Cahuita National Park snorkeling"],"local_keywords":["Puerto Viejo de Talamanca","Cahuita parque nacional","playas Caribe Sur Costa Rica","Punta Uva Costa Rica","refugio Gandoca-Manzanillo","tour de cacao Bribri","surf Salsa Brava","perezosos Puerto Viejo","Carnaval de Limon"],"hreflang":["en","es-CR"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"wildlife","status":"future"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Le Cameleon Boutique Hotel","price_tier":"luxury","virtuoso":false,"slh_member":true,"earning":"on application / host-Virtuoso / SLH trade / Fora","mor_posture":true,"note":"Playa Cocles beachfront; Small Luxury Hotels of the World; 51 rooms + 7 suites + 3 villas; the coast''s ceiling","source":"https://www.lecameleonhotel.com/"},{"name":"Tierra de Suenos Lodge & Wellness Center","price_tier":"premier-luxury","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"7 hardwood Caribbean bungalows, Playa Chiquita; wellness/yoga hideaway","source":"https://tierradesuenoslodge.com/"},{"name":"Namuwoki Lodge","price_tier":"premier","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"17 bungalows/villas, Playa Chiquita (Bribri ''Home of the Jaguar''); spa + restaurant","source":"https://www.namuwoki.com/"},{"name":"Physis Caribbean Bed & Breakfast","price_tier":"comfort-premier","virtuoso":false,"earning":"host-agency AOR / direct / Fora","mor_posture":true,"note":"intimate 4-room owner-run luxury B&B, Cocles","source":"https://physiscaribbean.net/about/"}],"source_verified":"2026-07-06","hero":{"query":"Puerto Viejo (Southern Caribbean), Costa Rica"},"geo":{"lat":9.6558,"lng":-82.7549}}'::jsonb, 86),
  ('punta-del-este-uruguay', '10S', 'Punta del Este & the Atlantic Coast, Uruguay', 'Uruguay', 'Calm bay, open Atlantic', 'live', 'verified', 'tropicalBeach', 'Montevideo & The Atlantic Coast', '{"tropical","romance","culinary"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["US State Dept Level 2 - Exercise Increased Caution (Uruguay; advisory dated 2025-05-07); reason = crime (C indicator); high-crime departments incl. Maldonado (Punta''s).","Two beaches: Playa Mansa (calm bay, family/swimming) vs Playa Brava (Atlantic surf, strong currents; La Mano is the warning). Swim patrolled zones only on Brava.","Signature set-pieces: Casapueblo sunset Ceremonia al Sol, La Mano, José Ignacio + Vik hotels, Isla de Lobos sea lions, Mallmann''s Garzón + Bodega Garzón (Tannat).","Peak = late-Dec to mid-Jan jet-set season; NYE is the single biggest night; premium villas/NYE book 3-6 months out; January most expensive hotel month.","Air: PDP (Punta del Este) seasonal Dec-Feb; year-round via MVD (Montevideo) + ~1.5 hr transfer. Tap water potable."],"safety":{"emergency":"911","police":"109","ambulance":"105","fire":"104","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":{"seasonal":"PDP (Capitán Corbeta CA Curbelo Intl, Punta del Este — busiest Dec-Feb)","year_round_gateway":"MVD (Carrasco Intl, Montevideo) + ~1.5 hr road transfer"},"water":"potable","primary_hazard":"Atlantic surf / riptides on Playa Brava (swim patrolled zones only; use Mansa bay for families)","trauma_path":"Punta private clinics (Cantegril + seasonal) → Montevideo (Hospital Británico / Hospital Italiano) → US medevac for catastrophic cases","petty_crime":"low but real — motorcycle snatch-theft + distraction/pickpocketing (weighted to Montevideo/nightlife); avoid after-dark ATMs, use registered taxis/ride-apps","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/uruguay","read":"2026-08-19","page_updated":"2025-12-10T13:00:39+00:00"}},"timing":{"peak":"late-Dec to mid-Jan (austral summer jet-set season — the money window; NYE the single hottest night)","peak_volume_note":"January = statistically most expensive hotel month","inflection_curve_start":"loads hard in Oct-Nov ahead of the holidays; top villas/NYE spoken for earlier","fire_date":"curve-start minus 1-2 weeks (~late Sep / early Oct for Dec-Jan peak); NYE + premium villas = 3-6 months lead (fire ~June-July)","shoulder":"Nov (late spring) and Mar (early autumn) — warm, thinner, better rates, much of the scene still open","low_season":"Jun-Aug (winter — cool, windswept, largely shuttered; deep-discount trough)","off_season_fill":"sell on price + José Ignacio/Garzón food-and-wine (Bodega Garzón, Mallmann) + Casapueblo + wellness/retreat quiet","events":[{"name":"New Year''s Eve (Reveillon) fireworks on the bay","date":"31 December","venue":"Playa Mansa horseshoe + ticketed beach events + hotel Reveillon"},{"name":"High-summer cultural season","months":"Dec-Feb","note":"concerts, ballet, exhibitions layered on the beach core"}]},"jewels":[{"name":"La Mano / Los Dedos (Playa Brava)","si_tag":"Tropical/Beaches","tier":"essential","source":"https://viator.com/Punta-del-Este-attractions/Los-Dedos-Playa-Brava-La-Mano-en-la-Arena/d4906-a7129","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Uruguay''s most iconic image — Mario Irarrázabal''s 1982 hand clawing out of the Atlantic sand, doubling as the surf-warning and the definitive Punta photo","si":"Tropical/Beaches","blurb":"Uruguay''s most iconic image — Mario Irarrázabal''s 1982 hand clawing out of the Atlantic sand, doubling as the surf-warning and the definitive Punta photo","when":"late-Dec to mid-Jan","commission":"free public sculpture; guided-tour affiliate + beach day"},{"name":"Playa Mansa vs Playa Brava two-mood beach day","si_tag":"Tropical/Beaches","tier":"essential","source":"https://silvias-trips.com/punta-del-este-uruguay-beach/","hook":"Sell both: Mansa for family swimming and sunset; Brava for surfers and the scene","si":"Tropical/Beaches","blurb":"Sell both: Mansa for family swimming and sunset; Brava for surfers and the scene","commission":"content-led; beach-club/day-pass + watersports affiliate"},{"name":"Isla de Lobos sea-lion boat excursion","si_tag":"Tropical/Beaches","tier":"comfort","source":"https://www.tripadvisor.com/Attraction_Review-g294066-d2630506-Reviews-Isla_de_Lobos-Punta_del_Este_Maldonado_Department.html","hook":"~2-hr guided boat tour from the Punta port around the offshore reserve","si":"Tropical/Beaches","blurb":"~2-hr guided boat tour from the Punta port around the offshore reserve","commission":"activities affiliate (Viator/GetYourGuide) / DMC boat charter"},{"name":"Cabo Polonio wild-coast day (Rocha)","si_tag":"Tropical/Beaches","tier":"comfort","source":"https://www.daytours4u.com/en/cabo-polonio-mount-ombues-day-tour.html/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The off-grid, 4×4-only dune outpost and sea-lion refuge up the coast — the wild counterpoint to glamour Punta, best as a guided full-day","si":"Tropical/Beaches","blurb":"The off-grid, 4×4-only dune outpost and sea-lion refuge up the coast — the wild counterpoint to glamour Punta, best as a guided full-day","when":"late-Dec to mid-Jan","commission":"activities affiliate / DMC 4x4 day-tour"},{"name":"La Barra strip","si_tag":"Tropical/Beaches","tier":"comfort","source":"https://upscapetravel.com/destinations/uruguay/punta-del-este/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The wooden-bridge village east of the peninsula — surf, galleries, boutiques, and the late-night bar scene; the bridge to José Ignacio","si":"Tropical/Beaches","blurb":"The wooden-bridge village east of the peninsula — surf, galleries, boutiques, and the late-night bar scene; the bridge to José Ignacio","when":"late-Dec to mid-Jan","commission":"villa MoR + activities/nightlife affiliate"},{"name":"Casapueblo sunset + Ceremonia al Sol (Punta Ballena)","si_tag":"romance","tier":"comfort","source":"https://www.guruguay.com/casapueblo-uruguay/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The most romantic set-piece on the coast — Páez Vilaró''s white citadel, the recorded farewell-to-the-sun poem over the Atlantic, sparkling wine on the terrace","si":"romance","blurb":"The most romantic set-piece on the coast — Páez Vilaró''s white citadel, the recorded farewell-to-the-sun poem over the Atlantic, sparkling wine on the terrace","when":"late-Dec to mid-Jan","commission":"entry non-commissionable; DMC/concierge sunset package + hotel stay"},{"name":"José Ignacio boho-luxe hideaway + Playa Vik","si_tag":"romance","tier":"luxury","source":"https://www.insidehook.com/travel/perfect-weekend-jose-ignacio-uruguay","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The prestige village as a honeymoon base — a Vik suite or a beach villa, dune beaches, art, and hush","si":"romance","blurb":"The prestige village as a honeymoon base — a Vik suite or a beach villa, dune beaches, art, and hush","when":"late-Dec to mid-Jan","commission":"Virtuoso/Fora consortia + villa MoR + DMC"},{"name":"NYE fireworks night on Playa Mansa","si_tag":"romance","tier":"comfort","source":"https://lafiestapunta.com/en/la-punta-fiesta-english/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The 31 December bay-side fireworks along ~40 miles of coast — a once-in-a-lifetime proposal/anniversary night","si":"romance","blurb":"The 31 December bay-side fireworks along ~40 miles of coast — a once-in-a-lifetime proposal/anniversary night","when":"late-Dec to mid-Jan","commission":"ticketed-event MoR (La Fiesta Punta-class) + hotel NYE package"},{"name":"Parador La Huella fish-on-the-sand (José Ignacio)","si_tag":"RHN / Culinary","tier":"premier","source":"https://www.roughguides.com/articles/best-restaurants-in-punta-del-este/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Fresh seafood on the beach at one of South America''s most famous restaurants — a beach-chic date night","si":"RHN / Culinary","blurb":"Fresh seafood on the beach at one of South America''s most famous restaurants — a beach-chic date night","when":"late-Dec to mid-Jan","commission":"direct reservation / DMC private experience"},{"name":"Francis Mallmann''s Restaurante Garzón (Garzón)","si_tag":"culinary","tier":"premier","source":"https://youshouldgohere.com/2024/09/francis-mallmann-garzon-uruguay/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The celebrity chef''s fire-cooked temple in a revived near-ghost town — feels like Provence in Uruguay","si":"culinary","blurb":"The celebrity chef''s fire-cooked temple in a revived near-ghost town — feels like Provence in Uruguay","when":"late-Dec to mid-Jan","commission":"direct reservation / DMC-packaged; Garzón hotel stay commissionable"},{"name":"Bodega Garzón — winery + fire kitchen (Tannat)","si_tag":"culinary","tier":"premier","source":"https://bodegagarzon.com/en/restaurant/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A modern architectural showpiece winery known worldwide for its award-winning Tannat, with a Mallmann-influenced fire-based restaurant. Tasting + lunch is a marquee inland day","si":"culinary","blurb":"A modern architectural showpiece winery known worldwide for its award-winning Tannat, with a Mallmann-influenced fire-based restaurant. Tasting + lunch is a marquee inland day","when":"late-Dec to mid-Jan","commission":"cellar-door direct / DMC wine-day package"},{"name":"Tannat + Uruguayan-wine tasting circuit","si_tag":"culinary","tier":"comfort","source":"https://bodegagarzon.com/en/restaurant/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Guided verticals of Tannat and the wider Maldonado/Garzón wine country — cellar-door or DMC-curated","si":"culinary","blurb":"Guided verticals of Tannat and the wider Maldonado/Garzón wine country — cellar-door or DMC-curated","when":"late-Dec to mid-Jan","commission":"DMC / activities affiliate"}],"faq":[{"q":"Which Punta del Este beach should I swim at — Mansa or Brava?","a":"Swim at Playa Mansa. The Mansa (calm Río de la Plata bay side) is gentle and family-friendly for swimming; Playa Brava faces the open Atlantic with strong waves and dangerous currents, best left to surfers and lifeguard-patrolled zones. The La Mano sculpture on Brava was built in 1982 as a literal warning about those currents.","source":"viator.com, 2026-07-07","si_tag":"tropical"},{"q":"Is Punta del Este good for a honeymoon?","a":"Yes — it is a co-primary romance destination. The boho-luxe play is a José Ignacio villa or a Vik suite, a Casapueblo sunset with sparkling wine (the Ceremonia al Sol has played daily since 1994), a fish-on-the-sand dinner at La Huella, and — if timing allows — NYE fireworks on the bay. José Ignacio is quieter and older-money than the peninsula''s party core.","source":"insidehook.com, 2026-07-07","si_tag":"romance"},{"q":"What''s the food-and-wine scene in Punta del Este?","a":"It is one of the region''s strongest. Parador La Huella grills the day''s catch on the José Ignacio sand (routinely on Latin America''s 50 Best); inland, Francis Mallmann''s Restaurante Garzón does open-fire cooking in a revived near-ghost town, and Bodega Garzón pours award-winning Tannat with a Mallmann-directed fire kitchen.","source":"roughguides.com, 2026-07-07","si_tag":"culinary"},{"q":"What''s the real risk to plan for in Punta del Este?","a":"The Atlantic surf. Playa Brava''s open-Atlantic waves and rip currents are the headline hazard — La Mano is literally the warning sign. Swim only in patrolled zones when lifeguards are on duty, and steer weak swimmers and children to the calm Playa Mansa bay side.","source":"viator.com, 2026-07-07","si_tag":"safety"},{"q":"Are the Isla de Lobos boat trip and Cabo Polonio dangerous?","a":"Not with a sanctioned operator. The ~2-hour Isla de Lobos crossing is open Atlantic — go on an operated launch with life jackets, and note that landing on the reserve is prohibited. Cabo Polonio is off-grid and reachable only by sanctioned 4×4 or horseback across the dunes; you cannot drive your own car in, so use an operator and treat it as a genuine wilderness day.","source":"daytours4u.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Punta del Este & the Atlantic Coast Travel Guide — Beaches, Casapueblo & José Ignacio | TravelWell","jsonld_type":"TouristDestination","freshness":"2026-07-07","search_language":"es-UY","long_tail_en":["things to do in Punta del Este","Casapueblo sunset ceremony","José Ignacio Uruguay","La Mano Punta del Este","Isla de Lobos boat tour sea lions","Punta del Este luxury villas","Parador La Huella","Bodega Garzón Francis Mallmann","Punta del Este New Year''s Eve","best time to visit Punta del Este","Cabo Polonio day trip","is Uruguay safe"],"local_keywords":["qué hacer en Punta del Este","atardecer en Casapueblo","José Ignacio","La Mano de Punta del Este","paseo a Isla de Lobos lobos marinos","alquiler de villas en Punta del Este","Parador La Huella","Bodega Garzón","Año Nuevo en Punta del Este","mejor época para visitar Punta del Este","Cabo Polonio"],"hreflang":["en","es-UY"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Fasano Punta del Este — Las Piedras","location":"inland Maldonado","tier":"ultra (resort-estate / AI anchor)","earning":"Fasano brand luxury / Amex FHR / Forbes — commission + amenities (UNVERIFIED %)"},{"name":"Playa Vik","location":"José Ignacio","tier":"ultra (Relais-tier)","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"},{"name":"Estancia Vik","location":"José Ignacio","tier":"ultra (Relais-tier)","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"},{"name":"Bahia Vik","location":"José Ignacio","tier":"ultra (Relais-tier)","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"},{"name":"The Grand Hotel Punta del Este","location":"peninsula, Playa Brava","tier":"luxury","earning":"consortia / brand luxury — commission + amenities (UNVERIFIED %)"}],"source_verified":null,"hero":{"query":"Punta del Este & the Atlantic Coast, Uruguay, Uruguay"},"geo":{"lat":-34.9633,"lng":-54.9506}}'::jsonb, 87),
