  ('rio-lagartos-mexico', '10S', 'Río Lagartos', 'Mexico', 'Spring breeding grounds of the flamingos', 'live', 'verified', 'oceanAerial', 'Yucatán (Mérida & Chichén Itzá)', '{"expedition","tropical"}', '{"tropical"}', '{"essential","ultra"}', null, null, '{"key_facts":["Ría Lagartos Biosphere Reserve — Yucatán''s flamingo capital; ~35 km boat safari, 400+ bird species","Flamingos breed Apr-Jul, counts near 40,000 — opposite of Celestún''s Nov-Mar peak","Las Coloradas pink lagoons colored by halophilic bacteria/algae; Mexico''s #2 salt operation; no-swim default, drones banned","Remote coast — nearest full trauma care Mérida ~2-2.5 hr; Tizimín ~1 hr, Valladolid ~1.5 hr","Cash economy (one ATM, runs dry); certified federal guides; sunscreen banned on-boat"],"safety":{"emergency_number":"911","advisory_level":"L1","book_enabled":true,"air_access_verified":true,"nearest_trauma":"Mérida private hospitals (~2-2.5 hr); Valladolid hospital (~1.5 hr) w/ 24-hr ambulance transfer; Tizimín (~1 hr) basic","remote_flag":true,"activity_fires":["boat-safari life vests + CONANP-licensed operator","sun/dehydration open water","no-touch/no-flush wildlife","Las Coloradas no-swim salt lagoon","remote medevac distance","mangrove/mosquito"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juá