  ('roatan-honduras', '10S', 'Roatán, Honduras (Bay Islands)', 'Honduras', 'Roatán', 'live', 'verified', 'oceanAerial', 'Honduras', '{"diveglobal","tropical"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Roatán sits on the Mesoamerican Barrier Reef, the second-largest coral-reef system on earth; Bay Islands ranked highest in coral health in the 2015 Mesoamerican assessment.","30+ dive shops on the west side; ~30 named dive sites within a 10-minute boat ride off West Bay/West End, with walls dropping past 100 ft and the El Aguila/Odyssey wrecks.","The Roatán Aggressor IV liveaboard runs Sat->Sat (18 guests, ~24-27 dives) across Roatán, Cayos Cochinos, and Utila.","Whale sharks are snorkel-only and protected; Utila (a short hop from Roatán) offers year-round potential peaking late March-April.","Roatán has an on-island recompression chamber (Cornerstone Hyperbaric, adjacent to Anthony''s Key Resort; DAN IPPN partner) — a first-response advantage for wall diving."],"safety":{"emergency":"911","hyperbaric_chamber":"Cornerstone Hyperbaric Chamber & Clinic, Sandy Bay (adjacent to Anthony''s Key Resort) — on-island recompression chamber + ER/lab/pharmacy, DAN International Preferred Provider Network partner","book_enabled":true,"bin":"BOOK WITH WARNING","air_access_verified":"Direct air into Juan Manuel Gálvez Intl (RTB), Roatán — Bay Islands reachable without transiting mainland gang zones","no_fly_after_diving":"18-24 hours before RTB departure flight (DAN protocol)","environmental":["west-wall depth discipline","currents on walls/channels","dengue (CDC)","bottled water only"]},"timing":{"peak_season":"mid-December to April (dry season); whale-shark peak late March-April; secondary Oct-Dec","best_visibility":"July-September","curve_start":"late November (dry-season); early March (whale-shark spike)","inflection":"December peak; late-March-April whale-shark peak","fire_date":"early-to-mid November (dry-season peak); mid-February (whale-shark spike)","booking_lead_months":"4-6","off_season_fill":"September-November (rain / hurricane-fringe) — value window, visibility-driven dive messaging","dive_calendar":true},"jewels":[{"name":"West End Wall + Mary''s Place","si_tag":"diveglobal","tier":"premier","source":"https://sundiversroatan.com/roatan-diving/","hook":"West End Wall is a top-tier wall dive","si":"diveglobal","blurb":"West End Wall is a top-tier wall dive","commission":"dive-resort package (Fora) / own-CLIA liveaboard"},{"name":"Shark Dive — Cara a Cara (via Waihuka)","si_tag":"Diving/GEA","tier":"comfort","source":"https://roatan.online/cara-cara-shark-dive","hook":"face-to-face with 8–15 Caribbean reef sharks at ~70 ft; ~$120 pp + 15% tax","si":"Diving/GEA","blurb":"face-to-face with 8–15 Caribbean reef sharks at ~70 ft; ~$120 pp + 15% tax","commission":"excursion via DMC/dive-resort (Fora)"},{"name":"Cayos Cochinos","si_tag":"Diving/Liveaboard","tier":"premier","source":"https://divemagazine.com/scuba-diving-travel/americas-caribbean/aggressor-adventures-roatan-aggressor-liveaboard-highlights","hook":"protected archipelago of pristine, less-dived reefs — a Roatán Aggressor itinerary highlight","si":"Diving/Liveaboard","blurb":"protected archipelago of pristine, less-dived reefs — a Roatán Aggressor itinerary highlight","commission":"own-CLIA liveaboard"},{"name":"El Aguila & Odyssey wrecks","si_tag":"diveglobal","tier":"premier","source":"https://diveintolife.blog/scuba-diving-in-roatan-honduras-west-bay-west-end/","si":"diveglobal","commission":"dive-resort package (Fora)"},{"name":"Whale-shark snorkel (Utila day-trip)","si_tag":"expedition","tier":"comfort","source":"https://www.thisisutila.com/post/utila-s-whale-shark-season-when-to-come-and-what-to-expect","si":"expedition","commission":"day-trip excursion via DMC (Fora)"},{"name":"Dolphin Encounter (Anthony''s Key Resort)","si_tag":"expedition","tier":"comfort","source":"https://anthonyskey.com/dolphin-programs/","hook":"get-in-the-water dolphin program in a natural lagoon; a 50-year AKR institution","si":"expedition","blurb":"get-in-the-water dolphin program in a natural lagoon; a 50-year AKR institution","commission":"AKR package/excursion (Fora)"},{"name":"Gumbalimba Park (ziplines, capuchins, iguanas, macaws)","si_tag":"expedition","tier":"essential","source":"https://roatan.online/gumbalimba-park","si":"expedition","commission":"DMC excursion (Fora/affiliate)"},{"name":"Iguana Farm (near French Cay, 2,700+ iguanas)","si_tag":"expedition","tier":"essential","source":"https://roatantourbase.com/excursion-guides/our-favorite-things-to-do-and-see-in-coxen-hole","si":"expedition","commission":"DMC excursion (affiliate)"},{"name":"Punta Gorda — Garífuna culture (UNESCO)","si_tag":"expedition","tier":"essential","source":"https://roatantourbase.com/excursion-guides/our-favorite-things-to-do-and-see-in-coxen-hole","hook":"Roatán''s oldest settlement; UNESCO-recognized Garífuna heritage, with the April 12 anniversary celebration","si":"expedition","blurb":"Roatán''s oldest settlement; UNESCO-recognized Garífuna heritage, with the April 12 anniversary celebration","commission":"cultural excursion via DMC (Fora/affiliate)"},{"name":"West Bay Beach","si_tag":"Tropical/Beaches","source":"https://www.royalcaribbean.com/inspire/what-is-roatan-known-for","hook":"Roatán''s iconic white-sand shoreline; warm shallows, reef snorkeling straight off the sand","si":"Tropical/Beaches","blurb":"Roatán''s iconic white-sand shoreline; warm shallows, reef snorkeling straight off the sand","commission":"anchors West Bay resort/villa stays (Fora / MoR villa)","tier_absent_reason":"not-sold"}],"faq":[{"q":"What''s the real risk to plan for?","a":"The load-bearing risk is mainland crime, and the plan is to stay in-zone. Violent crime and gang activity concentrate in the San Pedro Sula, Tegucigalpa, and Comayagua corridors, and Gracias a Dios Department carries a Level 4 \"Do Not Travel\" rating — all on the mainland. Fly direct into RTB, keep the trip airport → island, and never route overland through the gang zones.","source":"travel.state.gov, 2024-12-10","si_tag":"safety"},{"q":"Is diving Roatán''s walls dangerous — and can I fly out afterward?","a":"Wall diving rewards depth discipline and respect for the no-fly window, and Roatán has an unusual first-response advantage. Recreational divers work the crest and upper wall (≤60–100 ft); wreck and deep-wall profiles trend technical and are certification-gated. Allow no-fly-after-diving of 18–24 hours before your RTB flight, and note the on-island Cornerstone Hyperbaric Chamber (adjacent to Anthony''s Key Resort, a DAN partner) — a genuine safety edge for a wall-diving island. **What makes Roatán''s diving special? ** *(Dive Liveaboards / Diving)* Roatán delivers a serious wall reef within minutes of the dock plus a rare repeat-rate track record. Within a 10-minute boat ride off West Bay/West End you reach ~30 named dive sites, from a 15-ft sandy playground with feeding eagle rays to 100-ft+ wall drop-offs, wrecks, and canyon swim-throughs; CoCo View Resort claims the highest repeat rate of any dive resort worldwide (1,600+ guests five times over).","source":"anthonyskey.com, 2026-07-07","si_tag":"safety"},{"q":"How much is the Roatán reef fee, and is it required?","a":"Yes, it is mandatory and it is small. The Roatán Marine Park conservation fee is $10/year or $5/day, non-commissionable, and it funds the very reef you came to dive and snorkel — present it as the reef''s cover charge, never buried.","source":"roatan.online, 2026-07-07","si_tag":"tropical"},{"q":"Is Roatán good for a honeymoon?","a":"Yes — Roatán runs a genuine adults-only luxury lane on top of the diving. Ibagari Boutique Hotel is adults-only (12+), holds a Michelin Key 2025, and sits between West Bay and West End; private West Bay villas and sunset-cocktail liveaboard finales round out the romance product.","source":"guide.michelin.com, 2026-07-07","si_tag":"romance"},{"q":"Can I snorkel with whale sharks from Roatán?","a":"Yes, via a day-trip to neighboring Utila, and only by snorkel. Utila is one of the few places on earth with year-round whale-shark potential, peaking late March–April; the animals are protected, so it is surface snorkeling only — no diving with them and no touching.","source":"thisisutila.com, 2026-07-07","si_tag":"adventure"}],"seo":{"meta_title":"Roatán, Honduras (Bay Islands) — Diving, Liveaboards & West Bay Beach | TravelWell.World","search_language":"es-HN","local_keywords":["buceo Roatán","West Bay Roatán","Islas de la Bahía","tiburón ballena Utila","arrecife mesoamericano buceo","hoteles de buceo Roatán","cámara hiperbárica Roatán"],"long_tail_en":["Roatán diving guide","Roatán liveaboard Aggressor","West Bay Beach Roatán","whale shark snorkel Utila from Roatán","is Roatán safe to visit 2026","Roatán hyperbaric chamber"],"hreflang":["en","es-HN"],"jsonld_type":"TouristDestination","freshness":"2026-07-07","primary_keyword":"Roatán"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"live"},{"si":"tropical","status":"live"}],"ultra":[{"name":"Ibagari Boutique Hotel","lane":"Fora / Virtuoso preferred","mor":"Fora","tier":"Ultra/Luxury","note":"adults-only, Michelin Key 2025, boutique dive center"},{"name":"Las Verandas Hotel & Villas (Pristine Bay)","lane":"Fora / Virtuoso","mor":"Fora","tier":"Luxury","note":"villa resort + Black Pearl golf"},{"name":"Turquoise Bay Dive & Beach Resort","lane":"Fora","mor":"Fora","tier":"premier","note":"remote NE all-inclusive dive"},{"name":"Private West Bay villas (Arca / Lighthouse Estates)","lane":"MoR villa rung","mor":"MoR","tier":"Luxury","note":"full-villa buyout + DMC concierge"},{"name":"Roatán Aggressor private charter","lane":"own-CLIA","mor":"CLIA","tier":"Ultra/Premium","note":"full 18-berth whole-boat buyout"}],"source_verified":null,"hero":{"query":"Roatán, Honduras (Bay Islands), Honduras"},"geo":{"lat":16.3,"lng":-86.53}}'::jsonb, 92),
  ('ruta-de-las-flores-el-salvador', '10S', 'Ruta de las Flores, El Salvador', 'El Salvador', 'Ruta de las Flores', 'live', 'verified', 'mountainValley', 'El Salvador', '{"culture","culinary"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L1","advisory_reissued":"2026-06-25","book_enabled":true,"bin":"freely bookable (L1)","air_access_verified":true,"air_access_note":"San Salvador (SAL / Comalapa) + ~1.5–2 hr drive west; no visa for US stays under 90 days","volcano":{"name":"Santa Ana / Volcán Ilamatepec","status":"active, monitored","elevation_m":2381,"last_eruption":2005,"access":"guided summit only; scheduled departures; subject to activity-alert closure"},"health_notes":["bottled/purified water","dengue present — repellent, esp. green season"],"trauma_note":"Santa Ana / San Salvador hospitals; complex cases → US medical evacuation","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/el-salvador","read":"2026-08-19","page_updated":"2026-06-17T14:04:09+01:00"}},"timing":{"peak":"Dry season Nov–Apr (wildflower carpet Nov–Feb; year-round Juayúa weekend food festival); coffee-blossom micro-peak ~May","inflection":"Late Oct as rains taper; mid-to-late Apr before coffee blossom","green_season":"May–Oct (warm/wet, lush, lowest rates)","fire_date":"Mid-to-late October (dry-season crest, curve-start Nov 1 minus 1–2 wks); mid-April for the May coffee-blossom micro-peak"},"jewels":[{"name":"Juayúa Feria Gastronómica (weekend food festival)","si_tag":"culinary","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Dry season Nov–Apr","commission":"DMC/Viator/GetYourGuide weekend-anchor package; festival free, transport/guide/lodging earns","accessed":"2026-07-07"},{"name":"Coffee-finca tour + cupping (Apaneca / Ataco)","si_tag":"culinary","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Dry season Nov–Apr","commission":"DMC add-on or Santa Leticia direct-stay bundle; operator/hotel commissionable","accessed":"2026-07-07"},{"name":"Santa Ana volcano turquoise crater + Cerro Verde","si_tag":"expedition","tier":"essential","source":"https://sallysees.com/santa-ana-volcano-hike/ | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The signature GEA hero shot — a radioactive-bright sulphur lake in an active crater","si":"expedition","blurb":"The signature GEA hero shot — a radioactive-bright sulphur lake in an active crater","when":"Dry season Nov–Apr","commission":"Guided-summit product via DMC/Viator; guiding/transport commissionable, park fees not","accessed":"2026-07-07"},{"name":"Lake Coatepeque (volcanic caldera lake)","si_tag":"expedition","tier":"comfort","source":"https://www.booking.com/city/sv/coatepeque.html | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Dry season Nov–Apr","commission":"Lakeside boutique-hotel bookings (Cardedeu/Equinoccio) + boat excursions via operator","accessed":"2026-07-07"},{"name":"Apaneca Laguna Verde + Enganches/Ausol canopy zipline","si_tag":"expedition","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Crater lake ~5 km from Apaneca plus Central America''s longest cloud-forest ziplines","si":"expedition","blurb":"Crater lake ~5 km from Apaneca plus Central America''s longest cloud-forest ziplines","when":"Dry season Nov–Apr","commission":"DMC/operator activity affiliate","accessed":"2026-07-07"},{"name":"Los Chorros de la Calera / Siete Cascadas waterfall hike (Juayúa)","si_tag":"expedition","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Terraced falls with cliff jumps and rappels. The 7 Waterfalls hike requires a mandatory guide — flash-flood, slick-rock, and cliff-jump hazards make guided mandatory","si":"expedition","blurb":"Terraced falls with cliff jumps and rappels. The 7 Waterfalls hike requires a mandatory guide — flash-flood, slick-rock, and cliff-jump hazards make guided mandatory","when":"Dry season Nov–Apr","commission":"Local guide via DMC; commissionable through operator (guided-only)","accessed":"2026-07-07"},{"name":"Concepción de Ataco street art + coffee","si_tag":"culture","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"El Salvador''s most photogenic mural town — indigenous-history murals, Mirador de la Cruz, indigo-dye workshops, weekend street festival","si":"culture","blurb":"El Salvador''s most photogenic mural town — indigenous-history murals, Mirador de la Cruz, indigo-dye workshops, weekend street festival","when":"Dry season Nov–Apr","commission":"Mural-walk + coffee-finca combo via DMC; workshop fees via operator","accessed":"2026-07-07"},{"name":"Nahuizalco Mercado Nocturno (night market)","si_tag":"culture","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"One of the few places you''ll see women in traditional Pipil dress; wicker-craft workshops and a rare evening artisan market","si":"culture","blurb":"One of the few places you''ll see women in traditional Pipil dress; wicker-craft workshops and a rare evening artisan market","when":"Dry season Nov–Apr","commission":"Evening add-on to route itinerary; craft purchases direct","accessed":"2026-07-07"},{"name":"Joya de Cerén — Pompeii of the Americas (UNESCO)","si_tag":"culture","tier":"essential","source":"https://www.viator.com/San-Salvador-attractions/Joya-de-Ceren-Archaeological-Site/d5585-a15755 | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A 7th-century Maya farming village buried and preserved by volcanic ash; El Salvador''s only UNESCO World Heritage site. Open 9–4, closed Mondays; on-site museum","si":"culture","blurb":"A 7th-century Maya farming village buried and preserved by volcanic ash; El Salvador''s only UNESCO World Heritage site. Open 9–4, closed Mondays; on-site museum","when":"Dry season Nov–Apr","commission":"Guided heritage day trip via DMC/Viator; site entry non-commissionable","accessed":"2026-07-07"},{"name":"Tazumal ruins (Chalchuapa)","si_tag":"culture","tier":"essential","source":"https://andysworldjourneys.com/2025/10/16/joya-de-ceren-and-tazumal-ancient-history-in-el-salvador/ | Accessed 2026-07-07","timing":"year-round","timing_type":"ALWAYS-ON","hook":"El Salvador''s most important pyramids/ceremonial platforms, ~40 min from Joya de Cerén — the two pair into one Maya-heritage day","si":"culture","blurb":"El Salvador''s most important pyramids/ceremonial platforms, ~40 min from Joya de Cerén — the two pair into one Maya-heritage day","when":"year-round","commission":"Combined Maya-heritage day trip w/ Joya de Cerén via DMC/operator; entry non-commissionable","accessed":"2026-07-07"}],"faq":[{"q":"What is the Juayúa food festival?","a":"The Feria Gastronómica is the route''s flagship weekend market: every Saturday and Sunday, 11am–5pm, free entry, cash only, with the plaza filling with grills and pots — grilled meats $6–9, seafood ~$7, soups $3–4, pupusas ~$0.60, and roughly $10–20 feeds one person across multiple dishes. *[Culinary]*","source":"visitelsalvador.ai, Accessed 2026-07-07","si_tag":"culinary"},{"q":"Is Joya de Cerén worth visiting?","a":"Yes — it is El Salvador''s only UNESCO World Heritage site, a 7th-century Maya farming village buried and preserved by volcanic ash, earning the name \"Pompeii of the Americas.\" Open 9–4 and closed Mondays with an on-site museum, it pairs with the Tazumal ruins (~$5 entry, ~40 min away) into one Maya-heritage day. *[Culture & Heritage]*","source":"viator.com + andysworldjourneys.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"Is the Santa Ana volcano hike dangerous?","a":"It is managed, not casual. Santa Ana (Volcán Ilamatepec, 2,381 m) is an active, monitored volcano with a turquoise sulphur crater lake and volcanic gas near the rim; the ~4–5 hour summit hike is guided-only, at scheduled departure times, and is subject to closure on activity alerts. Do not attempt it unguided, and confirm open status before booking.","source":"sallysees.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"What outdoor adventures are on the Ruta de las Flores?","a":"The GEA spine runs from Santa Ana''s turquoise crater and Cerro Verde to Lake Coatepeque (a volcanic caldera lake beneath the volcano), plus Apaneca''s cloud-forest canopy ziplines (Los Enganches ~420 m lines) and the Laguna Verde crater lake ~5 km from Apaneca. Waterfall hikes at Los Chorros / Siete Cascadas round it out. *[GEA]*","source":"visitelsalvador.ai + sallysees.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where do couples stay on the Ruta de las Flores?","a":"Two romance bookends: coffee-finca boutique on the route itself — Hotel Santa Leticia, a 19-room working-estate lodge from ~USD 78/night — or lakeside luxe on Lake Coatepeque, where Cardedeu Residence is a 5-star hotel and Equinoccio a boutique lakeside stay with balcony rooms over the water. There is no international five-star flag on the route. *[Romance]*","source":"lastfrontiers.com + booking.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for?","a":"Guided-only adventure and mountain roads. The Siete Cascadas 7-waterfall hike (~6 hrs) requires a mandatory guide (~$15/person) because of flash-flood, slick-rock, and cliff-jump hazards; canopy ziplines are operator-run with harness and briefing. The route itself is a cobblestone-and-switchback mountain drive — go in daylight, watch for highland fog, and prefer a local driver at night.","source":"visitelsalvador.ai, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Ruta de las Flores, El Salvador — Coffee Towns, Santa Ana Volcano & the Flower Route | TravelWell.World","jsonld_type":"TouristDestination","search_language":"es-SV","freshness":"2026-07-07","local_keywords":["Ruta de las Flores El Salvador","Volcán Santa Ana","Juayúa festival gastronómico","Concepción de Ataco murales","Laguna Verde Apaneca","tour de café Ruta de las Flores","Lago de Coatepeque hotel","Joya de Cerén Pompeya de América"],"hreflang":["en","es-SV"],"primary_keyword":"Ruta de las Flores"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"},{"si":"culinary","status":"live"}],"ultra":[{"property":"Hotel & Restaurante Santa Leticia (Apaneca)","note":"Boutique coffee-finca ceiling on the route itself; 19 rooms, on-farm coffee program","earning":"hotel commission via consortia/bedbank","mor":"hotel/OTA","tier":"$$–$$$"},{"property":"Cardedeu (5-star) / Equinoccio + private villas, Lake Coatepeque","note":"Caldera-lake luxe bookend under Santa Ana","earning":"hotel commission (Cardedeu/Equinoccio); villas referral/affiliate only","mor":"hotel for flags; Airbnb/VRBO for villas","tier":"$$$–$$$$"},{"property":"San Salvador city 5-star bookend","note":"Arrival/departure luxe anchor; where international-flag commission lives (verify availability)","earning":"hotel commission via preferred/Virtuoso program","mor":"hotel","tier":"$$$–$$$$"}],"source_verified":null,"hero":{"query":"Ruta de las Flores, El Salvador, El Salvador"},"geo":{"lat":13.8722,"lng":-89.7928}}'::jsonb, 93),
  ('san-andres-colombia', '10S', 'San Andrés & Providencia, Colombia', 'Colombia', 'Coral islet, seven-colour sea', 'live', 'verified', 'tropicalBeach', 'Colombia''s Caribbean Coast', '{"tropical","liveaboard","romance","culture"}', '{"tropical"}', '{"essential","premier","luxury"}', null, null, '{"key_facts":["San Andrés — the ''Sea of Seven Colors'' — is Colombia''s Caribbean crown jewel, ringed by coral with 40+ mostly-shallow, high-visibility dive sites.","Providencia + Santa Catalina sit on the third-largest barrier reef in the world; Providencia rebuilt after Hurricane Iota (2020) and is open to tourism in 2026.","The Raizal are a Black Colombian Afro-Caribbean people; 20,000–30,000 speak San Andrés–Providencia Creole (Islander English) and most are trilingual.","Rondón — fish, conch, cassava, plantain and yam simmered in coconut milk — is the island''s signature dish (''run down'').","Mandatory Tourist Card (Tarjeta de Turismo) ~COP 153,000 (2026), bought at the airline counter before boarding the flight to ADZ."],"safety":{"emergency":"123","hospital":"Hospital Departamental Clarence Lynd Newball (San Andrés); hyperbaric/decompression chamber at Timothy Britton Hospital, San Andrés; serious cases referred off-island to mainland or US","book_enabled":true,"bin":"BOOK WITH WARNING","risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine/burundanga), extortion, express kidnapping occur throughout Colombia incl. cities (island crime skews to petty/beach theft + motorcycle snatch-and-grab)","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones (mainland-weighted)","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported (mainland-weighted)","N":"Natural Disaster — mainland volcano/earthquake/landslide; archipelago hurricane/tropical-storm exposure (Hurricane Iota, Nov 2020)"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"archipelago_in_named_danger":false,"island_crime_note":"island petty-crime (beach theft, motorcycle snatch-and-grab, scooter accidents) is lower and different from mainland violent crime; country-level advisory still renders in full at consent","air_access_verified":"ADZ (Gustavo Rojas Pinilla Intl) — direct international from Panama City (Copa, year-round) + domestic Colombian hubs; no nonstop US, but 1-stop via BOG/PTY (Avianca, Copa, LATAM). Providencia reached by ~20-min inter-island flight or catamaran.","remote_flag":true,"water":"bottled","vaccinations":"dengue/chikungunya/Zika present (peak rainy months); use insect protection; check CDC","scopolamine_caution":"''devil''s breath''/burundanga drugging — country-level; concentrates on mainland; never accept drinks/food from strangers"},"timing":{"peak":"Dec–Apr (dry); true peak January, then Feb–Mar (Colombians'' favorite domestic island)","inflection_curve_start":"early December","fire_date":"mid-to-late November (Dec–Jan peak); ~4–6 weeks before Semana Santa (late-Feb/early-Mar) for the Easter spike","event_peaks":[{"event":"Christmas–New Year","dates":"Dec 20–31","note":"maximum annual congestion; ADZ seats + rooms sell out"},{"event":"Semana Santa (Holy Week)","dates_2026":"Mar/Apr","note":"intense domestic coastal surge"}],"off_season_fill":"Sep–Nov (green season, lowest crowds, best deals); Jul–Aug secondary dry spell = best weather-to-cost; note higher dengue in rainy months"},"jewels":[{"name":"Sea of Seven Colors (Spratt Bight + lagoon)","si_tag":"tropical","tier":"essential","source":"https://colombia.travel/en/san-andres-island","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the seven-shade turquoise-to-cobalt water off the North End and the Aquarium/Haynes Cay flats; the island''s signature image","si":"tropical","blurb":"the seven-shade turquoise-to-cobalt water off the North End and the Aquarium/Haynes Cay flats; the island''s signature image","when":"Dec–Apr","commission":"hotel + boat-tour affiliate"},{"name":"Johnny Cay","si_tag":"tropical","tier":"essential","source":"https://www.lonelyplanet.com/colombia/san-andres-and-providencia/san-andres/attractions/johnny-cay-natural-regional-park/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"protected 4-ha coral islet ~1.5 km off San Andrés Town, coconut groves and the best white-sand beach around; colectivo boats from the town beach","si":"tropical","blurb":"protected 4-ha coral islet ~1.5 km off San Andrés Town, coconut groves and the best white-sand beach around; colectivo boats from the town beach","when":"Dec–Apr","commission":"GetYourGuide/Viator day-trip affiliate + park entry (non-comm)"},{"name":"La Piscinita","si_tag":"tropical","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g3493965-d3228746-Reviews-La_Piscinita-San_Andres_San_Andres_Island_San_Andres_and_Providencia_Department.html","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"calm natural snorkel pool south of El Cove, dive board + water slide, reef fish, seafood restaurant + gear rental","si":"tropical","blurb":"calm natural snorkel pool south of El Cove, dive board + water slide, reef fish, seafood restaurant + gear rental","when":"Dec–Apr","commission":"day-tour affiliate + on-site entry (non-comm)"},{"name":"West View (Mermaid Cave)","si_tag":"tropical","tier":"essential","source":"https://travelhapp.com/inspiration/things-to-do-in-san-andres-and-providencia","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dec–Apr","commission":"day-tour affiliate + entry (non-comm)"},{"name":"Rocky Cay + San Luis beach","si_tag":"tropical","tier":"essential","source":"https://colombia.travel/en/san-andres-island","hook":"walk-out cay off the quieter San Luis east coast, shallow wading to a wreck, the island''s mellow beach zone","si":"tropical","blurb":"walk-out cay off the quieter San Luis east coast, shallow wading to a wreck, the island''s mellow beach zone","commission":"San Luis hotel + day-tour affiliate"},{"name":"El Cove","si_tag":"tropical","tier":"essential","source":"https://www.lonelyplanet.com/colombia/san-andres-and-providencia/san-andres/attractions/la-piscinita/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the island''s deepest natural anchorage on the West side, quiet local-life counterpoint to the North End","si":"tropical","blurb":"the island''s deepest natural anchorage on the West side, quiet local-life counterpoint to the North End","when":"Dec–Apr","commission":"island-tour affiliate"},{"name":"Sea of Seven Colors reef dives + walls (Blue Wall, The Pyramid, Blue Diamond wreck)","si_tag":"Dive Liveaboards / Diving","tier":"essential","source":"https://bandadive.com/en","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Diving","when":"Dec–Apr","commission":"PADI operator direct/affiliate (Banda, Sharky)"},{"name":"Providencia barrier reef (third-largest on earth)","si_tag":"Dive Liveaboards / Diving","tier":"premier","source":"https://colombia.travel/en/providencia","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"wall and reef diving off Providencia/Santa Catalina, wilder and less-visited than San Andrés","si":"Dive Liveaboards / Diving","blurb":"wall and reef diving off Providencia/Santa Catalina, wilder and less-visited than San Andrés","when":"Dec–Apr","commission":"Providencia dive operator direct + inter-island flight"},{"name":"Providencia + Crab Cay + McBean Lagoon","si_tag":"romance","tier":"premier","source":"https://cuppatocopatravels.com/south-america/colombia/guide-isla-de-providencia-colombia/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the quiet-honeymoon jewel: Crab Cay ranked the island''s 1 snorkel spot, the McBean Lagoon marine park, near-empty coves","si":"romance","blurb":"the quiet-honeymoon jewel: Crab Cay ranked the island''s 1 snorkel spot, the McBean Lagoon marine park, near-empty coves","when":"Dec–Apr","commission":"Providencia DMC/boutique + marine-park fee (non-comm)"},{"name":"San Luis sunset stays","si_tag":"romance","tier":"essential","source":"https://colombia.travel/en/san-andres-island/native-inns","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the mellow east-coast beach strip, sunset-side quiet, small hotels and native inns for a low-key honeymoon","si":"romance","blurb":"the mellow east-coast beach strip, sunset-side quiet, small hotels and native inns for a low-key honeymoon","when":"Dec–Apr","commission":"San Luis hotel affiliate + host"},{"name":"Raizal culture + Islander Creole","si_tag":"culture","tier":"essential","source":"https://en.wikipedia.org/wiki/Raizal","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a living Afro-Caribbean nation: Creole English, Baptist chapels, kinship ties across the western Caribbean","si":"culture","blurb":"a living Afro-Caribbean nation: Creole English, Baptist chapels, kinship ties across the western Caribbean","when":"Dec–Apr","commission":"cultural-tour affiliate + native-inn stay"},{"name":"Rondón + coconut cuisine","si_tag":"culture","tier":"essential","source":"https://colombiaone.com/2025/09/02/colombia-food-san-andres/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the \"run down\" seafood-in-coconut-milk stew, breadfruit, crab, conch; a Raizal food-and-culture experience","si":"culture","blurb":"the \"run down\" seafood-in-coconut-milk stew, breadfruit, crab, conch; a Raizal food-and-culture experience","when":"Dec–Apr","commission":"food-tour affiliate + restaurant"},{"name":"Morgan''s Cave","si_tag":"culture","tier":"essential","source":"https://colombiaone.com/2023/12/21/guide-visit-san-andres-island-colombia/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"legendary Henry Morgan pirate-treasure hideout, now a small theme park/museum with exhibits and dance shows","si":"culture","blurb":"legendary Henry Morgan pirate-treasure hideout, now a small theme park/museum with exhibits and dance shows","when":"Dec–Apr","commission":"island-tour affiliate + entry (non-comm)"}],"faq":[{"q":"What are the best beaches and cays on San Andrés?","a":"Johnny Cay is the headline — a protected 4-ha coral islet ~1.5 km off San Andrés Town with the best white sand around, reached by colectivo boat — plus calm snorkel pools at La Piscinita and West View, and mellow Rocky Cay off San Luis. The lagoon is the famed \"Sea of Seven Colors.\"","source":"lonelyplanet.com, 2026-07-07","si_tag":"tropical"},{"q":"Is San Andrés good for scuba diving?","a":"Yes — it''s a shallow-water reef diver''s dream, with 40+ dive sites mostly at ~10–12 m, high-visibility and beginner-friendly, run through island PADI centers like Banda and Sharky. Providencia adds wall diving on the third-largest barrier reef in the world. Note it''s day-boat reef diving, not liveaboard-berth product.","source":"divescover.com, 2026-07-07","si_tag":"liveaboard"},{"q":"Is Providencia good for a quiet honeymoon?","a":"Yes — Providencia is the quiet-honeymoon jewel: near-empty coves, the McBean Lagoon marine park, and Crab Cay (its #1 snorkel spot, ~USD $6 park fee) reached by express boat. It''s rebuilt and open after Hurricane Iota (2020); reach it by ~20-minute inter-island flight or catamaran.","source":"cuppatocopatravels.com, 2026-07-07","si_tag":"romance"},{"q":"What language and culture will I find on San Andrés?","a":"A living Raizal Afro-Caribbean nation: 20,000–30,000 people speak San Andrés–Providencia Creole (Islander English) and most are trilingual, descended from 18th-century Jamaican settlers and enslaved Africans. The signature plate is rondón — fish, conch and root vegetables simmered in coconut milk.","source":"en.wikipedia.org, 2026-07-07","si_tag":"culture"},{"q":"What''s the real day-to-day risk on the island?","a":"Not the mainland headlines — the island''s real risks are petty/beach theft, motorcycle snatch-and-grab, scooter accidents and sea/riptide hazards. Renting a scooter or golf cart is the classic island loop, and scooter crashes plus snatch-and-grab are the two most common tourist mishaps: helmet on, valuables off the seat, drive in daylight.","source":"travelsafe-abroad.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"San Andrés & Providencia, Colombia — Sea of Seven Colors Diving, Beaches & Raizal Culture | TravelWell.World","jsonld_type":"TouristDestination","freshness":"2026-07-07","search_language":"es-CO","long_tail_en":["things to do in San Andres Colombia","San Andres diving Sea of Seven Colors","is San Andres safe 2026","Providencia island Colombia guide","San Andres tourist card cost 2026","Johnny Cay day trip San Andres","Providencia Crab Cay snorkeling"],"local_keywords":["San Andrés qué hacer","buceo San Andrés","Providencia","tarjeta de turismo San Andrés","Johnny Cay San Andrés","Cueva de Morgan","rondón San Andrés"],"hreflang":["en","es-CO"]},"booking":null,"si_checklist_25":null,"sis_present":["tropical","Dive Liveaboards / Diving","romance","culture"],"ultra":[{"name":"Casa Harb","type":"design boutique — island top-end (luxury, NOT palace-ultra)","routing":"Fora/Virtuoso preferred where participating + host","tier":"luxury"},{"name":"Decameron cluster (Isleño/San Luis/Los Delfines/Aquarium)","type":"mass-market all-inclusive","routing":"Online-Agency (OA) lane + host","tier":"premium (mass AI)"},{"name":"GHL Sunrise Hotel (Sunrise Beach)","type":"mid-market beachfront workhorse, Spratt Bight","routing":"GDS/bedbank + host","tier":"premier"},{"name":"Casa Iguana del Mar (villa)","type":"award-winning design villa, reef + white sand","routing":"MoR villa + host","tier":"luxury (thin)"},{"name":"Deep Blue (Providencia)","type":"boutique standout, Crab Cay gateway","routing":"direct/host","tier":"premium (remote boutique)"}],"source_verified":null,"hero":{"query":"San Andrés & Providencia, Colombia, Colombia"},"geo":{"lat":12.5847,"lng":-81.7006}}'::jsonb, 94),
  ('san-blas-guna-yala-panama', '10S', 'San Blas / Guna Yala, Panama', 'Panama', 'Guna Yala, island by island', 'live', 'verified', 'tropicalBeach', 'Panama', '{"tropical","romance","expedition","culture"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L2","advisory_date":"2024-09-23 (reissued; verified live 2026-07-07)","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":"Charter flights Albrook (PAC) → El Porvenir (PVE) / Corazón de Jesús (CZJ), ~40–45 min, ~$400/pax; OR 4x4 (steep rain-sensitive Cartí road, ~4–5 hrs) + boat, through Guna Cartí checkpoint (passport + ~$20/pax foreigner entry fee, cash, no ATMs)","remote_flag":true,"medevac_note":"No hospital in Guna Yala; most cays have no clinic; serious cases require medevac to Panama City / US (can exceed $50,000) — comprehensive medevac insurance mandatory","health_note":"Year-round dengue/malaria/zika/chikungunya risk; malaria-risk area — consult travel clinic on prophylaxis; drink bottled/treated water","gate_result":"PASS — Guna Yala/San Blas verified NOT in any L4/L3 named area of the Sept 23, 2024 Panama advisory (Level 2 country-wide). Bin = freely bookable (L2). Verified live 2026-07-07.","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/panama","read":"2026-08-19","page_updated":"2025-12-10T13:26:25+00:00"}},"timing":{"peak":"dry season Dec–Apr (calmer seas for sailing + the Colombia crossing)","inflection":"Oct–Nov (winter-escape + honeymoon + dry-season sailing dates on sale)","fire_date":"mid-to-late September (curve-start − 1–2 weeks); charters sell out ahead","off_season":"May–Nov green/rainy — value + solitude window, weather-tolerant travelers"},"jewels":[{"name":"Cayos Holandeses (Dutch Cays) sandbar","si_tag":"Tropical/Beaches","tier":"comfort","source":"https://www.seasanblas.com/blog/cayos-holandeses-one-of-the-best-san-blas-islands-to-visit","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the remote outer cluster — is widely rated the best snorkeling in the San Blas archipelago","si":"Tropical/Beaches","blurb":"the remote outer cluster — is widely rated the best snorkeling in the San Blas archipelago","when":"dry season Dec–Apr","commission":"multi-day charter / premium day-trip via DMC"},{"name":"Natural Pool / Starfish spot (Piscina Natural)","si_tag":"Tropical/Beaches","tier":"essential","source":"https://www.seasanblas.com/blog/complete-guide-to-visiting-san-blas-islands-panama","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical/Beaches","when":"dry season Dec–Apr","commission":"island-hopping day tour via DMC"},{"name":"Isla Pelícano / Cayos Limones lagoon","si_tag":"Tropical/Beaches","tier":"essential","source":"https://nomadsailors.com/blog/cayos-limones/","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical/Beaches","when":"dry season Dec–Apr","commission":"day tour / short cabaña stay"},{"name":"Castaway-island overnight cabaña","si_tag":"romance","tier":"essential","source":"https://www.tripadvisor.com/Hotels-g298434-San_Blas_Islands_Guna_Yala_Region-Hotels.html","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"dry season Dec–Apr","commission":"DMC cabaña package or private charter overnight"},{"name":"Isla Perro (Dog Island) wreck snorkel","si_tag":"expedition","tier":"essential","source":"https://sanblasadventures.com/san-blas-snorkeling/","si":"expedition","commission":"day tour / charter stop"},{"name":"Panama → Cartagena sailing charter (3–5 days)","si_tag":"expedition","tier":"comfort","source":"https://sanblasadventures.com/boat-colombia-to-panama/general-information/","si":"expedition","commission":"charter / CLIA lane — highest-value bookable in region"},{"name":"Guna mola textiles + living culture (1925 revolution, matrilineal congress, Dulegaya)","si_tag":"Culture & Heritage (future)","tier":"essential","source":"https://www.tourismpanama.com/culture-cuisine/indigenous-communities/guna/","timing":"dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Culture & Heritage (future)","when":"dry season Dec–Apr","commission":"cultural add-on / community visit via DMC (direct artisan purchases non-commissionable)"}],"faq":[{"q":"What''s the real risk to plan for in San Blas?","a":"Remoteness, not crime. There is no hospital and, on most cays, no clinic; serious illness or injury means evacuation to Panama City or the US, which can exceed $50,000. Comprehensive travel + medevac insurance is a condition of going, not an option — and dengue/malaria risk is year-round.","source":"smartraveller.gov.au, 2026-07-07","si_tag":"safety"},{"q":"Are the boat crossings and the 4x4 access road dangerous?","a":"Manageable but weather-governed. Everything moves by open boat, so insist on worn life vests, a licensed captain, and a real forecast check; the Colombia passage is 24–52 hours at open sea with no turning back mid-crossing. The overland Cartí route is a steep, rain-sensitive mountain road needing a 4x4 (4–5 hours). Guided only.","source":"sanblasadventures.com, 2026-07-07","si_tag":"safety"},{"q":"Which San Blas islands are best for beaches and snorkeling?","a":"The outer Cayos Holandeses (Dutch Cays) are widely rated the best snorkeling in the archipelago, with healthy reef and cushion starfish on the flats. Isla Perro holds the signature shallow-shipwreck snorkel a few metres from shore, while the Cayos Limones lagoon (Isla Pelícano, of *Money Heist* fame) offers the easiest crystal-shallow day-trip.","source":"seasanblas.com, 2026-07-07","si_tag":"tropical"},{"q":"Is San Blas good for a honeymoon?","a":"Yes, if you want elemental over polished. The set-piece is a private or near-private sand-cay cabaña — hammock, palm, reef at the doorstep, no wifi — from ~$56–$100/night full-board, scaling up to a private crewed catamaran overnight. Expect solar power and often no running water: this is the Caribbean before anyone built a lobby on it.","source":"tripadvisor.com, 2026-07-07","si_tag":"romance"},{"q":"What is the Panama-to-Cartagena sailing trip like?","a":"It''s a genuine passage, not a lagoon cruise. Three days threading the San Blas cays, then 24–52 hours of open-water crossing to Colombia; shared cabins run ~$525–$750 (meals + immigration paperwork included), private from ~$900+. Small boats have limited cabins and sell out weeks ahead for dry-season departures.","source":"sanblasadventures.com, 2026-07-07","si_tag":"expedition"},{"q":"Who are the Guna, and how do I enter the comarca?","a":"You enter on Guna terms. The Guna are a matrilineal people who won semi-autonomy in the 1925 revolution and still govern by congress under saila leaders; entry means a passport check and a per-person cash fee (~$20/foreigner) at the Cartí checkpoint, with no ATMs on the islands. Buy reverse-appliqué molas direct from the women who sew them.","source":"ampatours.com, 2026-07-07","si_tag":"culture"}],"seo":{"meta_title":"San Blas Islands (Guna Yala), Panama — Castaway Cays, Sailing & the Guna | TravelWell.World","search_language":"es-PA","local_keywords":["San Blas Guna Yala","islas San Blas Panamá","velero San Blas Cartagena","cómo llegar a San Blas desde Ciudad de Panamá","cabañas San Blas Guna Yala","molas guna","Cayos Holandeses"],"long_tail_en":["how to get to San Blas islands from Panama City","San Blas to Cartagena sailing trip","best San Blas islands for snorkeling","Isla Perro shipwreck snorkel","private catamaran charter San Blas","is San Blas Panama safe"],"hreflang":["en","es-PA"],"jsonld_type":"TouristDestination","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"type":"private crewed catamaran","name":"ZENITH / CruiseSanBlas / Charter in San Blas","note":"the luxury vehicle in Guna Yala — no branded ultra property exists","earning":"private-charter / CLIA lane"},{"type":"Panama City bookend hotel","name":"American Trade Hotel (Casco Viejo, Small Luxury Hotels of the World)","note":"consortia/Virtuoso-adjacent luxury anchor for the city night","earning":"Fora / consortia hotel commission"}],"source_verified":null,"hero":{"query":"San Blas / Guna Yala, Panama, Panama"},"geo":{"lat":9.57,"lng":-78.95}}'::jsonb, 95),
