ro da Liberdade São Paulo","São Paulo é seguro para turistas","onde ficar em São Paulo Jardins Itaim","melhores hotéis de luxo em São Paulo","passeio de helicóptero São Paulo"],"hreflang":["en","pt-BR"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Rosewood São Paulo (Cidade Matarazzo)","lane":"Virtuoso/Fora","mor":"consortia","tier":"ultra","note":"Jean Nouvel + Philippe Starck; the flagship opening"},{"name":"Palácio Tangará","lane":"Virtuoso/Fora","mor":"consortia","tier":"ultra","note":"Oetker Collection; Parque Burle Marx"},{"name":"Fasano São Paulo","lane":"Virtuoso/Fora","mor":"consortia","tier":"ultra","note":"Jardim Paulista; Baretto live-music room"},{"name":"Hotel Unique","lane":"consortia/Fora","mor":"consortia","tier":"ultra","note":"Ruy Ohtake half-moon landmark; Skye rooftop"},{"name":"Four Seasons São Paulo","lane":"FSPP/consortia","mor":"consortia","tier":"ultra","note":"business-district brand-loyalty anchor"}],"source_verified":null,"hero":{"query":"São Paulo, Brazil, Brazil"},"geo":{"lat":-23.5558,"lng":-46.6396}}'::jsonb, 104)
