insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('sayulita-mexico', '10S', 'Sayulita & the Riviera Nayarit', 'Mexico', 'Nayarit''s boho surf pueblo magico', 'live', 'verified', 'tropicalBeach', 'Nayarit (Riviera Nayarit & Sayulita)', '{"tropical","expedition","romance","ocean","culture","family","wildlife"}', '{"tropical"}', '{"essential","comfort","luxury"}', null, null, '{"key_facts":["Sayulita is a Pueblo Magico (since 2015) and the boho surf-and-art anchor of the southern Riviera Nayarit.","Bahia de Banderas filters Pacific swell into a forgiving 2-4 ft sand-bottom beach break - one of Mexico''s best beginner surf classrooms.","Islas Marietas ''hidden beach'' (Playa del Amor) is permit-capped: ~116 people/day, closed Mondays and Tuesdays, licensed operators only, no self-swim, life jacket + no fins, no under-10s or over-65s.","Humpback whales fill Banderas Bay roughly mid-December to early April, peak January-February.","Sayulita''s rapid growth outran its sewage infrastructure; major upgrades and an offshore outfall have been built, beach under permanent sanitary surveillance - drink bottled water, swim the protected Los Muertos cove.","Air access via Puerto Vallarta International (PVR), ~24 miles / 38-60 min south."],"safety":{"emergency":"911","hospital":"Nearest full trauma: Puerto Vallarta private hospitals (CMQ / San Javier / Hospital Joya), ~40-60 min south; local Sayulita/Bucerias clinics stabilize/transfer; complex cases PVR -> US/Guadalajara air-evac","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":true,"air_access_note":"Puerto Vallarta International (PVR), ~24 mi / 38-60 min south, in Jalisco but the regional gateway","riptides":"main beach + Los Muertos mellow; Patzcuarito/Carricitos open-Pacific and rip-prone (unsafe for beginner swimmers)","water":"bottled/purified only","dengue":"endemic seasonal risk, higher May-November","malaria":"not a practical risk in the tourist corridor","hurricane":"Pacific storm season ~June-October; insure/refundable summer rates","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry season; whales Dec-Mar peak Jan-Feb; surf year-round; highest rates + crowds)","inflection":"November (dry weather arrives, thinner crowds, whales opening) and late April (emptying out)","green":"May-Oct (rainy/value; ~20-40% off; warmest ocean; calm beginner surf)","holiday_event_peaks":["Christmas week","New Year","Semana Santa (late Mar/early Apr - verify calendar)"],"booking_window_lead_time":"peak/holiday 3-5 months; shoulder (Nov/late-Apr) 2-4 months; green season near-walk-up","fire_date":"curve-start minus 1-2 weeks: open peak (Dec-Apr) campaigns early October; whale-season push early November; Semana Santa campaign by mid-January; green-season value push ~2 weeks before the May shoulder edge","fill_the_beds":"green months: lead beginner surf (calmest/warmest water), long-stay villa value, yoga/wellness retreats, Huichol workshops, San Pancho calm; hedge whale messaging until December"},"jewels":[{"name":"Sayulita main beach + Calle Delfines flag street","si_tag":"Tropical / Beaches","status":"live","tier":"essential","hook":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","bookable_category":"village stay + surf lesson","source":"https://themexicoedit.com/things-to-do-in-sayulita-mexico/","si":"Tropical / Beaches","blurb":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","commission":"boutique-AOR + surf-operator affiliate; beach access pass-through"},{"name":"Playa de los Muertos (family swimming cove)","si_tag":"Family","status":"future","tier":"essential","hook":"Rock-protected roped swim area, no surf/boat traffic - the safe kids'' beach.","bookable_category":"villa/boutique stay","source":"https://www.sayulitalife.com/sayulita-beaches","si":"family","blurb":"Rock-protected roped swim area, no surf/boat traffic - the safe kids'' beach.","commission":"villa MoR / boutique-AOR; access pass-through"},{"name":"Beginner surf lesson (sand-bottom break)","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Mexico''s best beginner classroom - forgiving filtered 2-4 ft waves.","bookable_category":"surf lesson","source":"https://wildmex.com/activities/surf-lessons-sayulita-mexico/","si":"expedition","blurb":"Mexico''s best beginner classroom - forgiving filtered 2-4 ft waves.","commission":"surf-operator affiliate / referral"},{"name":"Huichol (Wixarika) art galleries + workshop","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Authentic beadwork/yarn-painting galleries and workshops with the stories behind the symbols.","bookable_category":"gallery + workshop","source":"https://www.roughguides.com/articles/sacred-sites-and-unique-art-supporting-indigenous-huichol-culture/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Authentic beadwork/yarn-painting galleries and workshops with the stories behind the symbols.","when":"Dec-Apr","commission":"workshop affiliate; gallery purchases pass-through"},{"name":"Islas Marietas hidden beach (Playa del Amor)","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Permit-capped national-park cove reached by swimming through a rock opening; booby colonies.","bookable_category":"licensed boat tour (permit required)","source":"https://wildmex.com/activities/tours-islas-marietas-playa-del-amor/","si":"ocean","blurb":"Permit-capped national-park cove reached by swimming through a rock opening; booby colonies.","commission":"licensed-tour affiliate / DMC; permit ~US$3-5 pass-through"},{"name":"Banderas Bay whale watching","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Morning humpback tours in the calving bay, Dec-Mar, peak Jan-Feb.","bookable_category":"whale-watch tour","source":"https://cms.vallartalifestyles.com/humpback-whale-season-begins-in-banderas-bay-and-beyond/","si":"wildlife","blurb":"Morning humpback tours in the calving bay, Dec-Mar, peak Jan-Feb.","commission":"affiliate 4-8% / DMC"},{"name":"San Pancho (San Francisco) — quiet-luxe + La Patrona polo","si_tag":"Romance & Honeymoons","status":"live","tier":"luxury","hook":"Slower, upmarket neighbor with polo (Oct-May), arts, wellness - a calm villa/honeymoon alternative.","bookable_category":"luxe villa + polo experience","source":"https://mexiconewsdaily.com/mexico-living/play-the-sport-of-kings-in-laid-back-san-pancho-nayarit/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Slower, upmarket neighbor with polo (Oct-May), arts, wellness - a calm villa/honeymoon alternative.","when":"Dec-Apr","commission":"DMC / luxury-villa MoR; polo affiliate"},{"name":"Bucerias Thursday Art Walk","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"~17 galleries open 7-9pm Thursdays, artists creating live; quieter than Sayulita.","bookable_category":"art walk + DMC transfer/dinner","source":"https://bestofbucerias.com/nearby/la-cruz-de-huanacaxtle/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"~17 galleries open 7-9pm Thursdays, artists creating live; quieter than Sayulita.","when":"Dec-Apr","commission":"DMC transfer + dining affiliate; walk pass-through"},{"name":"La Cruz de Huanacaxtle marina + Sunday Market","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"The Riviera''s largest artisan market on the marina docks (Sun, Nov-Apr) + sailing/charters hub.","bookable_category":"market + charter","source":"https://www.rivieranayaritfun.com/la-cruz-sunday-market-la-cruz-mercado","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"The Riviera''s largest artisan market on the marina docks (Sun, Nov-Apr) + sailing/charters hub.","when":"Dec-Apr","commission":"charter/DMC; market pass-through"},{"name":"Rincon de Guayabitos family beach","si_tag":"Family","status":"future","tier":"essential","hook":"Old-school calm-water Mexican-family beach town off the surf-tourist track.","bookable_category":"local hotel + DMC transfer","source":"https://lacasitadelapenita.com/activities/markets-in-our-area/","si":"family","blurb":"Old-school calm-water Mexican-family beach town off the surf-tourist track.","commission":"DMC transfer / host-AOR; beach pass-through"}],"faq":[{"q":"What''s the real risk to plan for?","a":"Water and rip currents, not crime. Sayulita''s rapid growth outran its sewage plant — major upgrades and an offshore outfall have since been built and the beach is under permanent sanitary surveillance, but drink only bottled water. Swim the protected coves (main beach, Los Muertos); exposed Patzcuarito/Carricitos are rip-prone and unsafe for beginner swimmers.","source":"globalpressjournal.com / sayulitalife.com, 2026-07-07","si_tag":"safety"},{"q":"How good is Sayulita for learning to surf?","a":"It''s arguably Mexico''s best beginner classroom. Bahía de Banderas filters swell into a forgiving 2–4 ft sand-bottom break where you fall onto soft sand in waist-deep water, and surf works year-round (calmest and warmest in the green season). Take a lesson before attempting the reef/rock point breaks.","source":"mexicotravelandleisure.com / sayulitalife.com, 2026-07-07","si_tag":"expedition"},{"q":"How do I visit the Islas Marietas Hidden Beach?","a":"Licensed operator only — you cannot swim or kayak in on your own. Access is capped at ~116/day, closed Mondays and Tuesdays, with life jacket and no fins mandatory and no children under 10 or adults over 65; you enter by jumping from the boat through a low rock opening. Book weeks ahead in season.","source":"vallartabyowner.com, 2026-07-07","si_tag":"ocean-adventures-—-future"},{"q":"What''s the Huichol art scene about?","a":"Living Indigenous art you can watch being made. Sayulita has deep Wixárika ties: galleries such as Galería Tanana (artist Cilau Valadez) and Tierra Huichol sell authentic beadwork and yarn paintings, and small workshops teach the beading and the meaning of the symbols. Gallery purchases are pass-through; workshops are the bookable wrapper.","source":"roughguides.com, 2026-07-07","si_tag":"culture-&-heritage-—-future"}],"seo":{"meta_title":"Sayulita & Riviera Nayarit Travel Guide 2026 — Surf, Marietas & Where to Stay | TravelWell.World","meta_description":"Plan Sayulita, Nayarit''s boho surf pueblo magico: beginner surf, Islas Marietas hidden-beach permit rules, whale season, Huichol art, straight water-infrastructure notes, Level 2 safety, and San Pancho/Bucerias/La Cruz jewels.","slug":"sayulita-mexico","jsonld_type":"TouristDestination","content_freshness":"2026-07-07","search_language":"es-MX","local_keywords":["qué hacer en Sayulita","Islas Marietas playa escondida","Riviera Nayarit","mejor época para visitar Sayulita","clases de surf en Sayulita","arte huichol Sayulita","San Pancho Nayarit","ballenas Bahía de Banderas","Playa de los Muertos Sayulita","villas en Sayulita"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"Tropical / Beaches","status":"live"},{"si":"expedition","status":"live"},{"si":"romance","status":"live"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"},{"si":"family","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Punta Mita — Four Seasons / St. Regis (own dossier)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso (Fora-eligible)","mor_posture":true,"note":"nearest branded ultra, ~25-30 min south; cross-ref its own dossier","source":"https://www.dreamexoticrentals.com/properties/LatinAmerica/mexico/PuntaMitaMexico-vacation-villas.htm"},{"name":"Amor Boutique Hotel / The Original Villa Amor (Sayulita)","price_tier":"luxury","virtuoso":false,"earning":"boutique-direct / host-AOR","mor_posture":true,"note":"31 oceanfront-hillside villas w/ plunge pools; on-village luxe anchor","source":"https://www.sayulitalife.com/amor-group-boutique-hotels"},{"name":"Haramara Retreat (Sayulita)","price_tier":"luxury","virtuoso":false,"earning":"retreat-direct / host-AOR","mor_posture":true,"note":"off-grid cliff-top wellness casitas, 360 yoga, open-air spa","source":"https://www.bontraveler.com/best-hotels-sayulita-mexico/"},{"name":"San Pancho luxe private villas","price_tier":"ultra","virtuoso":false,"earning":"on application / luxury-DMC or host villa AOR","mor_posture":true,"note":"full-service private villas in quiet-luxe neighbor; net-rate resale red","source":"https://www.puntademita-realestate.com/villasayulita18/"}],"source_verified":"2026-07-07","hero":{"query":"Sayulita & the Riviera Nayarit, Mexico"},"geo":{"lat":20.8697,"lng":-105.4419}}'::jsonb, 105),
  ('semuc-champey-guatemala', '10S', 'Semuc Champey', 'Guatemala', 'Turquoise pools on a natural limestone bridge', 'live', 'verified', 'mountainValley', 'Guatemala', '{"expedition"}', '{}', '{"essential"}', 'essential', null, '{"key_facts":["Pools sit atop a natural limestone bridge over the Cahabón River, which flows beneath them; Q''eqchi'' Maya ''where the river hides under the earth''.","Dry season Nov-Apr = clearest turquoise + safe current; rainy season May-Oct can turn pools brown and flood/close the site.","Lanquín-Semuc access road fully paved (concreted) in 2025; ~20-25 min by 4x4 from Lanquín.","Park open daily 08:00-16:00; entry Q50 foreigner / Q30 national (non-commissionable).","Nearest real hospital ~4 hours away in Cobán — remote-medevac destination."],"safety":{"emergency":{"police":"110","fire_ambulance":"122","proatur_asistur":"1500 / +502 2290 2810","asistur_whatsapp":"+502 5188 1819","red_cross":"125"},"book_enabled":true,"l3_disclosure":true,"state_dept_carveout":"Alta Verapaz not among the four named L4 zones (San Marcos, Huehuetenango, Zone 18, Villa Nueva); route via Cobán/Lanquín reads clean/normal-tourist","stay_in_zone":true,"air_access_verified":"via La Aurora GUA (Guatemala City) then overland Cobán-Lanquín","remote_flag":true,"remote_flag_detail":"HARD — nearest real hospital ~4 hrs away via Cobán → Guatemala City air-evac; evac-grade travel insurance mandatory; K''anba cave guided-only, no PPE; occasional protester roadblocks (consult PROATUR)"},"timing":{"season_shape":"dry-season destination (Nov-Apr); pools clearest & safest, road passable","curve_start":"early-to-mid November","peak":"December-March","shoulder_green":["April","late Oct / early Nov"],"off_season":"May-October (water clarity + closure risk)","booking_lead":"2-6 weeks in peak (pressure is on limited Lanquin lodge beds, not the park)","events":"regional: Cobán Rabín Ajau folkloric festival (late Jul/early Aug, rainy season)","fire_date":"~2026-10-20 to 2026-10-27 (curve-start minus 1-2 weeks)","note":"sharpen on live tracking — curve is weather/water-coupled"},"jewels":[{"name":"Turquoise pool terraces","si_tag":"expedition","tier":"essential","source":"https://www.roadaffair.com/the-ultimate-guide-to-visiting-semuc-champey/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"day-tour + lodge + DMC transfer commissionable; park entry non-commissionable","accessed":"2026-07-06"},{"name":"El Mirador viewpoint","si_tag":"expedition","tier":"essential","source":"https://www.roadaffair.com/the-ultimate-guide-to-visiting-semuc-champey/ (Accessed 2026-07-06)","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the postcard shot of the whole terrace chain from above; GEA/photography","si":"expedition","blurb":"the postcard shot of the whole terrace chain from above; GEA/photography","when":"year-round","commission":"bundled in guided day-program","accessed":"2026-07-06"},{"name":"K''anba candlelit caves (tubing)","si_tag":"expedition","tier":"essential","source":"https://www.getyourguide.com/guatemala-city-l1654/from-lanquin-semuc-champey-park-and-kanba-cave-guided-tour-t30495/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"guided day-tour via Viator/GetYourGuide/DMC; community cave fee non-commissionable","accessed":"2026-07-06"},{"name":"Lanquín Caves bat exodus (Grutas de Lanquín)","si_tag":"Wildlife/GEA","tier":"essential","source":"https://sallysees.com/semuc-champey-lanquin-guatemala/ (Accessed 2026-07-06)","hook":"Wildlife/GEA; thousands of bats stream out at sundown","si":"Wildlife/GEA","blurb":"Wildlife/GEA; thousands of bats stream out at sundown","commission":"add-on guided tour via lodge/DMC","accessed":"2026-07-06"},{"name":"Cahabón river tubing","si_tag":"expedition","tier":"essential","source":"https://www.adventurouskate.com/my-favorite-day-in-central-america-semuc-champey/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"outfitter/lodge day-tour (dry season only)","accessed":"2026-07-06"},{"name":"Las Marías village + cacao/chocolate workshop","si_tag":"Culture/Wellness","tier":"essential","source":"https://utopiaecohotel.com/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Culture/Wellness cross-cut; Q''eqchi'' community + Utopia''s working cacao farm chocolate-making","si":"Culture/Wellness","blurb":"Culture/Wellness cross-cut; Q''eqchi'' community + Utopia''s working cacao farm chocolate-making","when":"December-March","commission":"lodge-run experience (Utopia)","accessed":"2026-07-06"}],"faq":[{"q":"When is the best time to visit Semuc Champey?","a":"The dry season, November–April. That''s when the pools run clearest turquoise, the Cahabón current runs calm enough to swim and tube, and the now-paved road is reliably passable. Rainy season (May–October) can turn the pools muddy brown, spike current danger, and occasionally flood and close the site.","source":"adventurouskate.com, Accessed 2026-07-06","si_tag":"expedition"},{"q":"What wildlife can I see near Semuc?","a":"The signature sight is the Grutas de Lanquín bat exodus, when thousands of bats stream out at sundown — an add-on guided tour via lodge or DMC. The wider department is Alta Verapaz cloud-forest quetzal country, with the Biotopo del Quetzal reserve on the Cobán approach.","source":"sallysees.com, Accessed 2026-07-06","si_tag":"wildlife"},{"q":"What''s the real risk to plan for?","a":"Remoteness. Semuc is deep-rural: the nearest real hospital is ~4 hours away in Cobán, with no trauma center near the pools or caves, so evacuation-grade travel insurance is mandatory doctrine here. Also refuse dangerously overloaded 4×4 transfers (reports of 33 people in one truck) — book transport through a lodge or DMC.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Semuc Champey, Guatemala: Turquoise Pools, Caves & How to Visit (2026 Guide)","search_language":"en + es-GT","local_keywords":["cómo llegar a Semuc Champey","Semuc Champey mejor época para visitar","pozas turquesa Semuc Champey","grutas de Lanquín tour","cuánto cuesta la entrada a Semuc Champey","El Mirador Semuc Champey caminata"],"hreflang":["en","es-GT"],"jsonld_type":"TouristAttraction","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["expedition"],"ultra":[{"play":"No true ultra exists; construct it — best eco-lodge (Utopia) or premier Cobán base + fully private guide + private 4x4 transfer, as one adventure day in a luxe Antigua/Atitlan/Tikal circuit","route":"Martsam (mid-luxury DMC) or Fora advisor lane for US ultra clients","manner_of_record":"sell privacy + private guiding, not a nonexistent resort"}],"source_verified":"2026-07-06","hero":{"query":"Semuc Champey, Guatemala"},"geo":{"lat":15.5342,"lng":-89.9539}}'::jsonb, 106),
  ('sian-kaan-mexico', '10S', 'Sian Ka''an Biosphere Reserve', 'Mexico', '*If it''s a place the Maya named "where the', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","wildlife","tropical"}', '{"tropical"}', '{"comfort","premier"}', null, null, '{"key_facts":["UNESCO World Heritage; largest reserve in Quintana Roo, ~5,000 km2 of forest/mangrove/wetland/reef","Signature: boat + life-vest float on 1,200-year-old hand-dredged Maya trade canals","Biodiversity: 300+ birds, 100+ mammals, 1,200 plants, 52 fish species","Guided-only, remote; Punta Allen coastal access ~4h on 56km unpaved road from Tulum","Fees non-commissionable: CONANP entry ~MX$218 (~US$12) + fixed Muyil boat ~MX$1,000/person"],"safety":{"emergency":"911","advisory_level":"L2","nearest_trauma":"Tulum/Playa del Carmen clinics; evac to Cancun for major trauma; Chetumal (south) alt","malaria":"NONE in tourist zone; dengue present - HIGH mosquito load (wetland/mangrove)","water":"bottled/purified","hurricane":"Jun-Nov, peak Aug-Oct","special_rule":"REMOTE + GUIDED-ONLY - do not enter interior independently; guides carry comms; PFD on canal float","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dry season Nov-Apr (Dec-Apr optimal weather + best wildlife) - guided day-trip window","shoulder":"Nov and late-Apr edges","green":"Wet May-Oct (lush, fewer crowds, afternoon storms, hurricane overlap) - Tulum fill-the-beds","booking_window_lead_time":"2-4 weeks ahead in high season - DAILY VISITOR LIMITS cap seats (UNESCO biosphere rations access)","fill_the_beds":"No in-reserve beds; applies to Tulum pre/post stay - push May-Oct Tulum value + AM tours","holiday_event_peaks":"Dec holiday + New Year, Semana Santa compound the capped-seat crunch","campaign_start_trigger":"Early-book ~6-8 weeks ahead for Dec-Apr (seats capped); green-season Tulum-stay push May-Oct","source":"https://www.machupicchu.org/sian-kaan-biosphere-reserve-2026-unesco-world-heritage-day-trip-from-tulum.htm"},"jewels":[{"name":"Muyil ancient-Maya-canal float","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided expedition","source":"https://www.getyourguide.com/tulum-l248/tulum-sian-ka-an-biosphere-reserve-ancient-maya-canals-tour-t671649/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"boat run + life-vest drift on 1,200-yr-old Maya-dredged canals ·","si":"expedition","blurb":"boat run + life-vest drift on 1,200-yr-old Maya-dredged canals ·","when":"Dry season Nov-Apr","commission":"affiliate ~4-8% (Viator/GYG) / DMC on application"},{"name":"Guided lagoon boat expedition","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided boat tour","source":"https://www.mexicokantours.com/sian-kaan-adventure","si":"expedition","commission":"guided-tour affiliate / DMC (Mexico Kan Tours)"},{"name":"Kayak + snorkel Campechen lagoon","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided kayak/snorkel","source":"https://www.mexicokantours.com/sian-kaan-adventure","si":"expedition","commission":"affiliate/DMC"},{"name":"Birding day (300+ species)","si_tag":"Wildlife & Nature","status":"future","tier":"premier","bookable_category":"specialist nature tour","source":"https://lifeontheroam.com/sian-kaan-biosphere-reserve/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","when":"Dry season Nov-Apr","commission":"on application, small-group premium"},{"name":"Punta Allen coastal / sandbar","si_tag":"Tropical Islands","status":"future","tier":"comfort","bookable_category":"guided overland/boat","source":"https://www.thoroughlytravel.com/sian-kaan-biosphere-reserve/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dry season Nov-Apr","commission":"DMC/guide on application (~4h unpaved road)"}],"faq":[{"q":"What''s the real risk to plan for in Sian Ka''an?","a":"Remoteness, heat and mosquitoes — not marine hazards or crime. This is a mangrove/wetland reserve, so the mosquito load is high (repellent, cover up, especially dawn/dusk and rainy season), and sun, heat and dehydration are the genuine risks on a long, unpaved-road day. There is no interior infrastructure — carry water and travel with a comms-equipped guide.","source":"lifeontheroam.com / travel.state.gov, 2026-07-04","si_tag":"safety"},{"q":"What is the signature Sian Ka''an experience?","a":"The Muyil canal float. A boat runs you down ancient trade canals hand-dredged by Maya mariners over 1,200 years ago, then you drift downstream in a life vest on the natural current through mangrove lagoons — a natural lazy river. It is best in the calmer morning (fewer bugs), and bundled tours include transport, meals and an expert guide.","source":"getyourguide.com / lifeontheroam.com, 2026-07-04","si_tag":"expedition"},{"q":"What wildlife can I see in Sian Ka''an?","a":"A great deal — the reserve''s four ecosystems host 300+ bird species, 100+ mammals, 1,200 plants and 52 fish species, with a good chance of dolphins on the lagoon runs. Dedicated dawn birding tours are the way to see the most; wildlife is the reserve''s purpose-built anchor, so book a naturalist-guided product rather than a bare boat ride.","source":"lifeontheroam.com, 2026-07-04","si_tag":"wildlife"},{"q":"How do you actually visit Sian Ka''an, and can I stay inside?","a":"As a guided day trip from Tulum — you cannot sleep in the biosphere, as there is no lodging of any kind inside. Access is guided-only with rationed daily visitor limits, so book 2–4 weeks ahead in high season. Note the fixed Muyil boat driver is transport-only; if you want interpretation, book a nature-guide product, not the bare boat fee.","source":"machupicchu.org / roamingaroundtheworld.com, 2026-07-04","si_tag":"planning"},{"q":"When is the best time to visit Sian Ka''an?","a":"November–April, the dry season, is best — Dec–April brings optimal weather and the best wildlife viewing. Whatever the season, morning tours are calmer with fewer bugs; the May–October wet season is lush and quieter but brings afternoon storms and hurricane overlap (Jun–Nov). Because seats are capped, book earliest for the Dec–April and holiday windows.","source":"machupicchu.org / lifeontheroam.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Sian Ka''an Biosphere Reserve: UNESCO Wetlands Tour","meta_description":"Sian Ka''an - UNESCO biosphere south of Tulum: float 1,200-year-old Maya canals, birds and mangroves. Guided-only, remote; how and when to go.","slug":"sian-kaan-mexico","primary_keyword":"Sian Ka''an Biosphere Reserve","long_tail":["Sian Ka''an Muyil canal tour","Sian Ka''an from Tulum","Sian Ka''an boat tour","Sian Ka''an birding","Punta Allen Sian Ka''an"],"search_language":"bilingual (en + es-MX)","local_keywords":["Reserva de la Biosfera Sian Ka''an","Sian Ka''an desde Tulum","canales mayas Muyil","tour Muyil Sian Ka''an","Sian Ka''an que hacer","avistamiento de aves Sian Ka''an","Punta Allen Sian Ka''an"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"wildlife","status":"future"},{"si":"tropical","status":"future"}],"ultra":[],"source_verified":"2026-07-04","hero":{"query":"Sian Ka''an Biosphere Reserve, Mexico"},"geo":{"lat":19.5333,"lng":-87.6167}}'::jsonb, 107),
  ('suchitoto-el-salvador', '10S', 'Suchitoto, El Salvador', 'El Salvador', 'Colonial town on Lake Suchitlan', 'live', 'verified', 'kyoto', 'El Salvador', '{"romance","expedition","culture"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L1","advisory_date":"2026-06-25","advisory_source":"https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/el-salvador-travel-advisory.html","book_enabled":true,"bin":"freely bookable (L1)","air_access_verified":true,"air_access_note":"San Salvador (SAL), ~1 hour by road to Suchitoto","trauma":"San Salvador (~1 hr) for definitive trauma; serious cases → US medical evacuation; carry evac insurance","notes":["Lake boat safety: confirm life vests, morning outings, avoid overloaded boats","Cobblestone footing slick when wet/at night","Bottled water only","Dengue-risk country — repellent, esp. rainy season","Flag: Australia/Canada still carry heightened-caution advisories"],"fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/el-salvador","read":"2026-08-19","page_updated":"2026-06-17T14:04:09+01:00"}},"timing":{"peak":"Nov–Apr (dry season); migratory birds on Lago Suchitlán Nov–Feb; Feb arts-festival weekends","inflection":"mid-to-late October rains taper; peaks Dec holidays + Feb festival weekends","green_offseason":"May–Oct (misty lake, Los Tercios waterfall at full flow, rooms available)","fire_date":"early October for Nov–Apr season; second pulse late-Dec/early-Jan for Feb festival + Jan–Feb birding peak"},"jewels":[{"name":"Iglesia Santa Lucía + cobblestone centro","si_tag":"romance","tier":"essential","source":"https://mylatinlife.com/suchitoto-el-salvador-travel-guide/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Nov–Apr","commission":"free/self-guided; monetized via boutique stay + DMC evening program","accessed":"2026-07-07"},{"name":"Sunset boat on Lago Suchitlán","si_tag":"romance","tier":"comfort","source":"https://www.passporttheworld.com/destinations/central-america/el-salvador/things-to-do-in-suchitoto-el-salvador/ (Accessed 2026-07-07)","hook":"Water safety is the live risk: insist on life vests, use a reputable operator, go in the morning to avoid afternoon wind-chop","si":"romance","blurb":"Water safety is the live risk: insist on life vests, use a reputable operator, go in the morning to avoid afternoon wind-chop","commission":"DMC-packaged (commissionable) or walk-up (non-commissionable)","accessed":"2026-07-07"},{"name":"Café-teatro & courtyard dining","si_tag":"romance","tier":"comfort","source":"https://www.hotel-scoop.com/charming-los-almendros-de-san-lorenzo/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Nov–Apr","commission":"boutique-hotel F&B / DMC dining reservations","accessed":"2026-07-07"},{"name":"Isla de los Pájaros birding, Lago Suchitlán","si_tag":"expedition","tier":"comfort","source":"https://blog.walkingwithelsalvador.org/2023/01/off-beaten-path-birding-on-lake.html (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"over 200 species recorded, including herons, egrets, cormorants, pelicans, storks, and Amazon and Belted kingfishers","si":"expedition","blurb":"over 200 species recorded, including herons, egrets, cormorants, pelicans, storks, and Amazon and Belted kingfishers","when":"Nov–Apr","commission":"DMC-packaged birding tour w/ naturalist (commissionable)","accessed":"2026-07-07"},{"name":"Los Tercios hexagonal-basalt waterfall","si_tag":"expedition","tier":"essential","source":"https://www.passporttheworld.com/destinations/central-america/el-salvador/things-to-do-in-suchitoto-el-salvador/ (Accessed 2026-07-07)","si":"expedition","commission":"guided hike via DMC/local guide (commissionable when packaged)","accessed":"2026-07-07"},{"name":"Guazapa volcano & civil-war trail hikes","si_tag":"expedition","tier":"comfort","source":"https://everythingelsalvador.com/what-to-do-suchitoto/ (Accessed 2026-07-07)","hook":"Longer jungle hikes to former FMLN camp sites should be guided — trail-finding, terrain, and historical context all argue for a local guide","si":"expedition","blurb":"Longer jungle hikes to former FMLN camp sites should be guided — trail-finding, terrain, and historical context all argue for a local guide","commission":"guided DMC/local operator (commissionable)","accessed":"2026-07-07"},{"name":"Indigo / añil dyeing workshop (Arte Añil)","si_tag":"culture","tier":"essential","source":"https://www.passporttheworld.com/destinations/central-america/el-salvador/things-to-do-in-suchitoto-el-salvador/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov–Apr","commission":"workshop fee (non-commissionable) or DMC-packaged (commissionable)","accessed":"2026-07-07"},{"name":"Permanent Festival of Art & Culture (Feb weekends)","si_tag":"culture","tier":"comfort","source":"https://www.frommers.com/destinations/suchitoto/things-to-do/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov–Apr","commission":"DMC festival-weekend package + stay (commissionable); admissions often free (non-commissionable)","accessed":"2026-07-07"},{"name":"Centro Arte para la Paz","si_tag":"culture","tier":"essential","source":"https://everythingelsalvador.com/what-to-do-suchitoto/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Plate Museum, and the indigo-workshop drop-in fee — small local cash entries, non-commissionable; include them as itinerary value, not as revenue lines","si":"culture","blurb":"the Plate Museum, and the indigo-workshop drop-in fee — small local cash entries, non-commissionable; include them as itinerary value, not as revenue lines","when":"Nov–Apr","commission":"admission (non-commissionable) folded into DMC cultural walk","accessed":"2026-07-07"},{"name":"Joya de Cerén + San Andrés Maya day (UNESCO)","si_tag":"culture","tier":"comfort","source":"https://whc.unesco.org/en/list/675/ (Accessed 2026-07-07)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov–Apr","commission":"DMC/receptive-operator day tour (commissionable) or Viator/GetYourGuide (affiliate)","accessed":"2026-07-07"}],"faq":[{"q":"Is Suchitoto good for a romantic weekend?","a":"Yes — it is El Salvador''s best-preserved colonial town and its strongest romance play: cobblestone streets, boutique colonial casas, lake sunsets and candlelit courtyard dinners over a two- or three-night escape. The flagship stay is Los Almendros de San Lorenzo, an 11–12-room restored 200-year-old mansion from roughly US$136/night. *[Romance & Honeymoons]*","source":"hotel-scoop.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the birding like on Lake Suchitlán?","a":"Excellent and dense in season. The lake hosts 200+ bird species — herons, egrets, cormorants, storks and kingfishers among them — and they concentrate into a tighter, more photographable population roughly November–February as the lake drops. Morning boat tours from Puerto Turístico San Juan run to the bird-rich islands and flooded forest. *[GEA]*","source":"blog.walkingwithelsalvador.org + travelandtourworld.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"What is Suchitoto known for culturally?","a":"It is the country''s cultural capital, anchored by the 1853 whitewashed Iglesia Santa Lucía on the plaza. Indigo (añil) is the signature craft, with hands-on Nahuat-technique dyeing workshops at studios like Arte Añil, and the Permanent Festival of Art & Culture (3+ decades, February weekends) plus nearby UNESCO Joya de Cerén deepen the heritage draw. *[Culture & Heritage]*","source":"frommers.com + mylatinlife.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"What''s the real risk to plan for?","a":"Footing, not crime. The historic core is genuine river-stone cobblestone — uneven and slick when wet or at night — so flat, gripping footwear is the mitigation. The ~20-minute Los Tercios waterfall walk crosses slick, uneven basalt columns, worst in the wet season, so a local guide is preferred. Drink bottled water and use repellent, as El Salvador is a dengue-risk country.","source":"passporttheworld.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Suchitoto, El Salvador — Colonial Lake Town, Boutique Escape & Birding Guide","meta_description":"El Salvador''s best-preserved colonial town: cobblestone streets, the 1853 Iglesia Santa Lucía, Lake Suchitlán birding, Los Tercios waterfall, and indigo workshops — a romantic weekend escape, now US Level 1.","search_language":"es-SV","long_tail_en":["things to do in Suchitoto El Salvador","Suchitoto colonial town guide","Lake Suchitlán boat tour birding","Los Tercios waterfall Suchitoto","indigo dyeing workshop Suchitoto","Suchitoto boutique hotels romantic","Joya de Cerén day trip Suchitoto"],"local_keywords":["qué hacer en Suchitoto","Lago Suchitlán","Los Tercios cascada","Iglesia Santa Lucía Suchitoto","talleres de añil Suchitoto","hoteles boutique Suchitoto","Festival Permanente de Arte y Cultura Suchitoto","avistamiento de aves Lago Suchitlán"],"hreflang":["en","es-SV"],"jsonld_type":"TouristDestination","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"property":"Los Almendros de San Lorenzo","type":"boutique-colonial flagship (ceiling)","mor":"agent-of-record on ground program + villa MoR","tier":"comfort"},{"property":"Casa 1800 Suchitoto","type":"design-forward heritage boutique","mor":"bedbank/consortia where available","tier":"comfort"},{"property":"La Posada de Suchitlán","type":"classic hacienda comfort","mor":"bedbank/OTA","tier":"comfort"},{"note":"No true ultra/5-star bed inventory in Suchitoto — boutique-colonial ceiling; ultra earning is ground-program agent-of-record + villa MoR"}],"source_verified":null,"hero":{"query":"Suchitoto, El Salvador, El Salvador"},"geo":{"lat":13.9389,"lng":-89.0294}}'::jsonb, 108),
  ('teotihuacan-mexico', '10S', 'Teotihuacán', 'Mexico', '*If it''s floating over the Avenue of the Dead', 'live', 'verified', 'kyoto', 'Mexico City', '{"culture"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["UNESCO World Heritage Site (inscribed 1987); among the largest pre-Columbian cities in the Americas","Pyramid of the Sun ~65–70 m, ~248 steps; Sun-summit climb status contradictory for 2026 (verify on arrival)","Pyramid of the Moon reopened for climbing 19 May 2025 — first section only (5 platforms / 47 steps)","Entrance ~90 MXN (~US$4.50); open daily ~9am–5pm; INAH-managed","~50 km / ~1 hr NE of Mexico City in the State of México; sits on a major obsidian deposit"],"safety":{"emergency":"911","nearest_trauma":"Mexico City (CDMX) — carve-out base, ~1 hr transfer","advisory_level":"L2","advisory_note":"Day-trip from CDMX L2 carve-out base; corridor not a named restricted area; L2 disclosure applied","book_enabled":true,"tourist_zone_carveout":"CDMX (Level 2) base; State of México corridor L2, no named restriction","air_access_verified":"via MEX (Mexico City Int''l) + ~50 km / ~1 hr ground transfer","altitude":"~2,300 m (~7,545 ft) — same band as CDMX; pyramid climb = altitude + exertion","ams_note":"CDMX-acclimatized travelers add little; climbing steep steps at 2,300 m is strenuous","water":"bottled/purified only; carry >=1.5 L pp (open, shadeless site)","sun_heat":"intense sun at altitude year-round; little shade; hat/sunscreen mandatory","source":"https://travel.state.gov/en/international-travel/travel-advisories/mexico.html (Accessed 2026-07-05)","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"inflection_curve_start":"early-to-mid November (dry season opens, clear ballooning skies)","peak":"December–March (busiest + clearest/driest; weekends 2–3x crowded)","fire_date":"~October 20–27 (curve-start ~Nov 3 minus 1–2 wks) — directional, sharpen on live tracking","shoulder":"late April–May and late October–early November","green":"May–October rainy-season midweek (mornings usually flyable)","booking_lead":"2–4 wks peak weekends/equinox; 3–7 days weekday off-peak (directional)","off_season_specials":"May–Oct rainy season midweek balloon + cave-lunch discount bundles","event_peaks":["Spring equinox ~Mar 20–21 — 100,000+ visitors, white/red dress, early gate ~6am, crowd spike","Balloon year-round, dry-season (Nov–Apr) best — durable revenue spine"],"source":"https://findmemexico.com/teotihuacan-weather-guide-best-times-to-visit-2025-updated/; https://en.wikipedia.org/wiki/Spring_equinox_in_Teotihuac%C3%A1n; https://teotihuacanballoons.com/ (Accessed 2026-07-05)"},"jewels":[{"si_tag":"expedition","name":"Sunrise hot-air-balloon over the Avenue of the Dead","tier":"premier","source":"https://wefly.com.mx/en (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the flagship: lift off in the cold dark, watch the Pyramid of the Sun turn gold, champagne toast on landing","si":"expedition","blurb":"the flagship: lift off in the cold dark, watch the Pyramid of the Sun turn gold, champagne toast on landing","when":"December–March","commission":"DMC balloon-bundle + OTA affiliate; operator activity commission","accessed":"2026-07-05"},{"si_tag":"expedition","name":"Pyramid of the Moon first-section climb (reopened 2025)","tier":"essential","source":"https://mexiconewsdaily.com/travel/pyramid-of-the-moon-teotihuacan-reopens-2025/ (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the newly re-accessible ascent giving the best down-the-Avenue axial view","si":"expedition","blurb":"the newly re-accessible ascent giving the best down-the-Avenue axial view","when":"December–March","commission":"curated-recommend within guided GEA day-tour","accessed":"2026-07-05"},{"si_tag":"expedition","name":"Temple of the Feathered Serpent (Quetzalcoatl), the Citadel","tier":"essential","source":"https://www.mexicotravelandleisure.com/blog/teotihuacan-mexico-pyramids/ (Accessed 2026-07-05)","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the carved feathered-rattlesnake facade, quieter than the big pyramids","si":"expedition","blurb":"the carved feathered-rattlesnake facade, quieter than the big pyramids","when":"year-round","commission":"guided-zone day-tour upsell","accessed":"2026-07-05"},{"si_tag":"Global Expedition Adventures / Romance","name":"Evening light-and-sound / projection show (seasonal)","tier":"comfort","source":"https://www.mexicotravelandleisure.com/blog/teotihuacan-mexico-pyramids/ (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the pyramids lit after dark; a distinct GEA/Romance evening product when running","si":"Global Expedition Adventures / Romance","blurb":"the pyramids lit after dark; a distinct GEA/Romance evening product when running","when":"December–March","commission":"DMC evening add-on (verify schedule)","accessed":"2026-07-05"},{"si_tag":"Culture & Heritage / Eat","name":"La Gruta cave restaurant (near Pyramid of the Sun)","tier":"comfort","source":"https://www.lagruta.mx/index_en.php (Accessed 2026-07-05)","hook":"dining inside a natural cave ~300 m from the Pyramid of the Sun, used since pre-Columbian times; dishes ~150–350 MXN","si":"Culture & Heritage / Eat","blurb":"dining inside a natural cave ~300 m from the Pyramid of the Sun, used since pre-Columbian times; dishes ~150–350 MXN","commission":"DMC lunch-bundle; à-la-carte non-commissionable","accessed":"2026-07-05"},{"si_tag":"culture","name":"Obsidian artisan workshops / carving","tier":"essential","source":"https://www.mexicotravelandleisure.com/blog/teotihuacan-mexico-pyramids/ (Accessed 2026-07-05)","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the valley''s namesake stone worked into blades, figurines, and jewelry by local artisans; a hands-on heritage micro-experience","si":"culture","blurb":"the valley''s namesake stone worked into blades, figurines, and jewelry by local artisans; a hands-on heritage micro-experience","when":"December–March","commission":"DMC artisan-stop add-on; retail affiliate potential","accessed":"2026-07-05"},{"si_tag":"culture","name":"Museo del Sitio + botanical garden","tier":"essential","source":"https://lugares.inah.gob.mx/en/node/4528 (Accessed 2026-07-05)","hook":"the on-site museum framing the city''s scale and cosmology before the walk","si":"culture","blurb":"the on-site museum framing the city''s scale and cosmology before the walk","commission":"bundled in guided day-tour (admission via site fee)","accessed":"2026-07-05"}],"faq":[{"q":"Is climbing the pyramids hard — what''s the real risk?","a":"Altitude, sun and steps, not crime. Climbing at **~2,300 m** with steep steps and limited handrails is a cardiovascular + heat-exposure event; the site is open and shadeless. Ascend slowly with per-level rest, carry ≥1.5 L water, wear sun protection, and avoid midday climbs. If you''re already acclimatized to Mexico City you''ll feel little extra.","source":"mexicotravelandleisure.com, 2026-07-05","si_tag":"safety"},{"q":"Can you still climb the Pyramid of the Sun in 2026?","a":"Verify on arrival — the Sun-pyramid summit climb status is contradictory across 2026 sources. What''s confirmed: the **Pyramid of the Moon reopened for climbing on 19 May 2025**, first section only (five platforms / 47 steps), giving the best down-the-Avenue axial view.","source":"mexiconewsdaily.com, 2026-07-05","si_tag":"culture"},{"q":"Is Teotihuacán good for a couples experience?","a":"Yes — the private sunrise balloon, a champagne toast on landing, and breakfast or lunch in the **La Gruta cave restaurant ~300 m from the Pyramid of the Sun** make a natural anniversary set-piece, bookable as a full private-basket, private-guide day out of CDMX.","source":"lagruta.mx, 2026-07-05","si_tag":"romance"}],"seo":{"meta_title":"Teotihuacán Sunrise Balloon & Pyramids — Day-Trip from Mexico City | TravelWell.World","meta_description":"Float over the Pyramids of the Sun and Moon at sunrise, then climb the Avenue of the Dead — a UNESCO day-trip from Mexico City with certified balloon operators. Book the private experience.","search_language":"en + es-MX","hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-05","local_keywords":["vuelo en globo teotihuacán amanecer desde cdmx","se puede subir a la pirámide del sol 2026","pirámide de la luna reapertura escalar","tour teotihuacán desde ciudad de méxico","restaurante la gruta teotihuacán","equinoccio de primavera teotihuacán 2026","precio entrada teotihuacán inah"],"keywords_en":["teotihuacan hot air balloon sunrise from mexico city","can you climb the pyramid of the sun 2026","pyramid of the moon reopened climbing","teotihuacan day trip from cdmx","la gruta cave restaurant teotihuacan","teotihuacan spring equinox 2026","teotihuacan entrance fee 2026"],"primary_keyword":"Teotihuacán"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"}],"ultra":[{"name":"Four Seasons Mexico City balloon experience","type":"ultra stay (CDMX) + private Teotihuacán balloon","earning_path":"Fora/Virtuoso-consortia FS stay commission + private balloon activity commission via DMC","tier":"ultra","source":"https://www.fourseasons.com/mexico/hot-air-balloon-experiences/ (Accessed 2026-07-05)"},{"name":"Private balloon + private guided zone + La Gruta cave lunch","type":"premier private day-experience (not a stay)","earning_path":"premium private DMC day-package","tier":"premier day-experience","source":"https://www.viator.com/tours/Mexico-City/Private-Tour-and-Hot-Air-Balloon-Flight-over-Teotihuacan/d628-366381P1 (Accessed 2026-07-05)"},{"note":"No true ultra STAY at Teotihuacán — nearest ultra stay = CDMX. Accurate tier: premier day-experience."}],"source_verified":"2026-07-05","hero":{"query":"Teotihuacán, Mexico"},"geo":{"lat":19.6925,"lng":-98.8438}}'::jsonb, 109),
  ('tikal-guatemala', '10S', 'Tikal / Flores', 'Guatemala', 'Temple IV at sunrise, Peten jungle', 'live', 'verified', 'kyoto', 'Guatemala', '{"expedition","culture"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["UNESCO World Heritage Site (1979); 576 km² biosphere with 3,000+ identified Maya structures.","Temple IV rises 64.6 m (212 ft) — the tallest pre-Columbian structure in the Americas; the classic sunrise perch above the canopy.","Tikal park entry Q150 (~US$19.50) foreigners; open 06:00–18:00; sunrise/sunset permits +Q100 each (mandatory guide).","Flores/Santa Elena (FRS) Mundo Maya airport takes 4–5 daily flights from Guatemala City (GUA) on TAG Airlines & Avianca; Tikal is 65 km / ~1 hr from Flores.","Base is the island town of Flores on Lake Petén Itzá; the wildlife includes jaguars, 5 cat species, howler/spider monkeys, coatis, ocellated turkeys and 400+ birds."],"safety":{"emergency":{"police":"110","fire_ambulance":"122 / 123","tourist_assistance_PROATUR":"1500"},"hospital":"Nearest hospital in Santa Elena/Flores (~1 hr); serious cases air-evac to Guatemala City. HARD remote-medevac flag — Tikal is jungle-remote.","book_enabled":true,"l3_disclosure":true,"state_dept_carveout":"Tikal/Petén explicitly cleared; avoid San Marcos/Huehuetenango/Zone-18/Villa Nueva","stay_in_zone":true,"air_access_verified":"Flores FRS airport, 4–5 daily flights from GUA (TAG/Avianca) — bypasses all four named L4 zones","malaria":"Petén is a CDC-named P. vivax malaria chemoprophylaxis department AND an annual dengue department — pre-trip travel-medicine consult + bite prevention required","water":"Bottled/filtered only"},"timing":{"inflection_curve_start":"early-to-mid November","peak":"December–March (Semana Santa spike late Mar/early Apr; TWW best-month = January)","fire_date":"2026-10-24","shoulder":"May; late-Oct/early-Nov","green":"May–October (Sep–Oct wettest / true off-season)","booking_lead":"3–6 weeks peak; 8–12 weeks for Semana Santa (lead pressure is on beds)","off_season_specials":"green-season lodge discounts + empty-Tikal wildlife/birding positioning","event_peaks":["Semana Santa (Holy Week)","Uaxactún equinox sunrise (Mar/Sep)"]},"jewels":[{"name":"Sunrise on Temple IV (above the canopy)","si_tag":"GEA","status":"live","hook":"3 a.m. torch-lit climb of the 212-ft temple; dawn breaks over an ocean of jungle with howler monkeys roaring in.","bookable_category":"guided sunrise tour","tier":"comfort","source":"https://www.getyourguide.com/guatemala-l169110/from-flores-tikal-sunrise-archaeological-tour-t535277/ + Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","blurb":"3 a.m. torch-lit climb of the 212-ft temple; dawn breaks over an ocean of jungle with howler monkeys roaring in.","when":"year-round","commission":"GetYourGuide/Viator affiliate; private via host-IATA land services","accessed":"2026-07-06"},{"name":"Waking-jungle wildlife walk","si_tag":"GEA / Wildlife","status":"live","hook":"Howler + spider monkeys, coatis, toucans, ocellated turkeys, 400+ birds on the dawn/wildlife-focus tour.","bookable_category":"archaeology+wildlife guided tour","tier":"comfort","source":"https://www.tripadvisor.com/Attractions-g292015-Activities-c42-Tikal_National_Park_Peten_Department.html + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA / Wildlife","blurb":"Howler + spider monkeys, coatis, toucans, ocellated turkeys, 400+ birds on the dawn/wildlife-focus tour.","when":"December–March","commission":"GYG/Viator affiliate; DMC upsell","accessed":"2026-07-06"},{"name":"Cerro Cahuí Biotope (El Remate)","si_tag":"GEA","status":"live","hook":"1,500-acre lakeside rainforest reserve; Tzu''unte (6 km) & Los Ujuxtes (5 km) trails to three-lake lookouts, 300 birds, swimming dock.","bookable_category":"guided hike + lodge night","tier":"essential","source":"https://www.fodors.com/world/mexico-and-central-america/guatemala/el-peten/things-to-do/sights/reviews/biotopo-cerro-cahui-578646 + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"1,500-acre lakeside rainforest reserve; Tzu''unte (6 km) & Los Ujuxtes (5 km) trails to three-lake lookouts, 300 birds, swimming dock.","when":"December–March","commission":"host-IATA land services + lodge night","accessed":"2026-07-06"},{"name":"Lake Petén Itzá boat sunset","si_tag":"GEA","status":"live","hook":"Local boats onto the 32 km lake at golden hour — Flores glowing on the water, swim from docks, kayak/paddleboard.","bookable_category":"boat tour","tier":"essential","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","si":"expedition","blurb":"Local boats onto the 32 km lake at golden hour — Flores glowing on the water, swim from docks, kayak/paddleboard.","commission":"affiliate + lodge concierge","accessed":"2026-07-06"},{"name":"ARCAS Wildlife Rescue","si_tag":"GEA / Wildlife","status":"live","hook":"Ethical confiscated-wildlife rehab center near Flores — a mission-driven visit.","bookable_category":"visit/volunteer (local)","tier":"essential","source":"https://www.passportandpixels.com/things-to-do-in-flores-guatemala-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA / Wildlife","blurb":"Ethical confiscated-wildlife rehab center near Flores — a mission-driven visit.","when":"December–March","commission":"thin/donation-driven — goodwill add-on","accessed":"2026-07-06"},{"name":"Yaxhá sunset (Temple 216)","si_tag":"Culture & Heritage","status":"future","hook":"Guatemala''s 3rd-largest Maya site over twin lagoons — half Tikal''s fee, far fewer people, classic sunset from Temple 216.","bookable_category":"guided sunset day-tour","tier":"comfort","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Guatemala''s 3rd-largest Maya site over twin lagoons — half Tikal''s fee, far fewer people, classic sunset from Temple 216.","when":"year-round","commission":"GYG/Viator affiliate or host-IATA land services","accessed":"2026-07-06"},{"name":"Uaxactún astronomical observatory (Group E / E-VII-sub)","si_tag":"Culture & Heritage","status":"future","hook":"The Maya world''s most famous equinox/solstice observatory, ~1 hr past Tikal; equinox-sunrise pilgrimage.","bookable_category":"private/small-group day-tour","tier":"premier","source":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8078784/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"The Maya world''s most famous equinox/solstice observatory, ~1 hr past Tikal; equinox-sunrise pilgrimage.","when":"December–March","commission":"host-IATA land services (private)","accessed":"2026-07-06"},{"name":"Flores island (Sky Bar sunset)","si_tag":"Culture & Heritage","status":"future","hook":"Painted island town — cobbled lanes, rooftop sunset bars over Lake Petén Itzá; the decompression counterpoint to the jungle.","bookable_category":"boutique-hotel stay","tier":"essential","source":"https://www.passportandpixels.com/things-to-do-in-flores-guatemala-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Painted island town — cobbled lanes, rooftop sunset bars over Lake Petén Itzá; the decompression counterpoint to the jungle.","when":"December–March","commission":"hotel affiliate / host-IATA","accessed":"2026-07-06"},{"name":"Playa Chechenal (San Miguel)","si_tag":"Culture & Heritage","status":"future","hook":"Local lakeside beach across from Flores (~US$2) where Petén families barbecue and swim — off the tourist track.","bookable_category":"DIY (boat/walk)","tier":"essential","source":"https://www.indietraveller.co/flores-guatemala-travel-guide/ + Accessed 2026-07-06","timing":"December–March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Local lakeside beach across from Flores (~US$2) where Petén families barbecue and swim — off the tourist track.","when":"December–March","commission":"none meaningful — local-color add-on","accessed":"2026-07-06"}],"faq":[{"q":"What''s the real risk to plan for at Tikal?","a":"Mosquito-borne disease, not crime. Petén is a CDC-named malaria (*P. vivax*) prophylaxis department and reports dengue annually — so book a travel-medicine consult before departure, use DEET/picaridin, cover up at dawn/dusk, and choose screened or AC rooms.","source":"cdc.gov Yellow Book, 2026-07-06","si_tag":"safety"},{"q":"How remote is Tikal if something goes wrong?","a":"Genuinely remote — plan for it. The nearest hospital is in Santa Elena/Flores (~1 hr from the park); anything serious means air evacuation to Guatemala City, so travel medical + medevac insurance is not optional here. Save the PROATUR tourist-assistance line (1500).","source":"livinginguatemala.com, 2026-07-06","si_tag":"safety"},{"q":"Is the Tikal sunrise tour worth the 3 a.m. start?","a":"For most, yes — it''s the signature. You leave Flores around 3 a.m. for the ~45–60 min / 65 km drive, enter at 4 a.m. with a mandatory guide, and climb the 212 ft Temple IV to watch dawn break over the canopy as howler monkeys roar in. Skip it only if you can''t manage steep wooden stairs in the dark.","source":"getyourguide.com / livinginguatemala.com, 2026-07-06","si_tag":"expedition"},{"q":"Do I need a guide at Tikal, and is Yaxhá worth adding?","a":"Hire a guide — without one Tikal is impressive but confusing (group ~US$39–65, private ~US$65–104). For a quieter Maya sunset, add Yaxhá: Guatemala''s third-largest site over twin lagoons, about half Tikal''s entry fee, far fewer people.","source":"livinginguatemala.com / indietraveller.co, 2026-07-06","si_tag":"culture"},{"q":"What wildlife will I actually see at Tikal?","a":"On a dawn/wildlife-focus walk, reliably: howler and spider monkeys, coatis, toucans, ocellated turkeys and many of the reserve''s 400+ birds — jaguars and the five cat species exist but are rarely seen. Keep distance and never feed the monkeys, which can be aggressive around food.","source":"livinginguatemala.com, 2026-07-06","si_tag":"wildlife"},{"q":"When is the best time to visit Tikal?","a":"The dry season (roughly Nov–April) gives reliable sunrise views; January is the sweet spot — dry, cooler, wildlife active, and ahead of the Feb–April crowd wall — because the wettest months (Sep–Oct) bring muddy trails and Semana Santa (Holy Week) tightens Flores beds hard. Book lodges 8–12 weeks ahead for Holy Week.","source":"livinginguatemala.com, 2026-07-06","si_tag":"planning"}],"seo":{"meta_title":"Tikal & Flores, Guatemala Travel Guide — Maya Sunrise, Petén Jungle & Lake Petén Itzá | TravelWell.World","meta_description":"Climb Temple IV at sunrise, base on the painted island of Flores, and explore Yaxhá, Uaxactún and the Petén jungle — how to visit Tikal well, safely, and at the right time.","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"en, es-GT","long_tail_en":["Tikal sunrise tour from Flores","Temple IV sunrise Tikal","Tikal vs Yaxhá sunset","best time to visit Tikal 2026","Flores Guatemala boutique hotels Lake Petén Itzá","Tikal malaria dengue precautions","Uaxactún equinox observatory tour","Cerro Cahuí El Remate hike"],"local_keywords":["tour Tikal desde Flores","amanecer Templo IV Tikal","atardecer en Yaxhá","Uaxactún observatorio astronómico","qué hacer en Flores Petén","Lago Petén Itzá atardecer","Biotopo Cerro Cahuí El Remate","entrada Parque Nacional Tikal precio"],"hreflang":["en","es-GT"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"}],"ultra":[{"name":"Las Lagunas Boutique Hotel","why_ultra":"300-acre private nature reserve on Lake Quexil, two monkey islands, spa, on-site Maya-artifact museum, private jacuzzis + lake-view rooms; minutes from Tikal/Yaxhá/Uaxactún — the most complete luxury base in Petén.","earning":"consortia/agent rate + amenity block; agent-of-record commission","virtuoso_value_add":"upgrade, breakfast, resort/spa credit, early/late, VIP welcome (confirm current program)","mor":"Fora / host-IATA agent-of-record","tier":"luxury"},{"name":"La Lancha (Francis Ford Coppola)","why_ultra":"Coppola-family lodge on a rainforest hillside over Lago Petén Itzá; sunset-terrace bar, pools/hot tubs, brand cachet across the water from Flores.","earning":"consortia/agent rate; Family Coppola Hideaways trade terms","virtuoso_value_add":"amenity/credit + upgrade where program allows (verify)","mor":"Fora / host-IATA","tier":"luxury (boutique 4-star)"},{"name":"Bolontiku Boutique Hotel & Spa","why_ultra":"Boat-in lakefront boutique + spa on Lake Petén Itzá (15–30 min from Flores) — the arrive-by-boat seclusion play.","earning":"direct/consortia agent rate","virtuoso_value_add":"boat transfer + spa credit where negotiable (verify)","mor":"host-IATA agent-of-record","tier":"premier / luxury"}],"source_verified":"2026-07-06","hero":{"query":"Tikal / Flores, Guatemala"},"geo":{"lat":17.222,"lng":-89.6237}}'::jsonb, 110)
